create function repair_private.amount(p jsonb,k text) returns bigint language plpgsql immutable set search_path='' as $$
declare n numeric; begin
 if not coalesce(p->>k,'') ~ '^\d{1,13}$' then raise exception 'Invalid money field: %',k; end if;
 n:=(p->>k)::numeric; if n>1000000000000 then raise exception 'Amount too large'; end if; return n::bigint;
end $$;
create function repair_private.calc(input jsonb) returns jsonb language plpgsql immutable set search_path='' as $$
declare x jsonb; arr jsonb:='[]'; q numeric; price bigint; discount bigint; tax int; base bigint; taxsum bigint:=0; netsum bigint:=0; pending int:=0; excluded boolean; begin
 if jsonb_typeof(input) is distinct from 'array' or jsonb_array_length(input) not between 1 and 200 then raise exception 'Add 1 to 200 items'; end if;
 for x in select value from jsonb_array_elements(input) loop
  if length(trim(coalesce(x->>'description',''))) not between 1 and 300 then raise exception 'Item description required (max 300 characters)'; end if;
  q:=(x->>'quantity')::numeric;
  if q is null or q<=0 or q>100000 or q<>round(q,3) then raise exception 'Invalid item quantity'; end if;
  price:=case when x->>'unit_minor' is null then null else repair_private.amount(x,'unit_minor') end;
  discount:=repair_private.amount(x,'discount_minor');tax:=(x->>'tax_bps')::int;excluded:=coalesce((x->>'excluded')::boolean,false);
  if tax is null or tax not between 0 and 10000 then raise exception 'Invalid tax'; end if;
  base:=case when price is null then null else round(q*price)::bigint-discount end;
  if base<0 then raise exception 'Discount exceeds line price'; end if;
  if not excluded then
   if price is null then pending:=pending+1; else netsum:=netsum+base;taxsum:=taxsum+round(base*tax/10000.0)::bigint;end if;
  end if;
  arr:=arr||jsonb_build_array(jsonb_build_object('id',coalesce(x->>'id',md5(x::text||jsonb_array_length(arr)::text)),'category',left(coalesce(x->>'category','Repair Items'),100),'description',trim(x->>'description'),'quantity',q,'unit',left(coalesce(x->>'unit','item'),30),'unit_minor',price,'discount_minor',discount,'tax_bps',tax,'excluded',excluded,'notes',left(coalesce(x->>'notes',''),500),'net_minor',case when excluded then 0 else base end,'tax_minor',case when excluded then 0 when base is null then null else round(base*tax/10000.0)::bigint end));
 end loop;
 if netsum>1000000000000 then raise exception 'Total too large'; end if;
 return jsonb_build_object('lines',arr,'net_minor',netsum,'tax_minor',taxsum,'total_minor',netsum+taxsum,'pending',pending);
end $$;
create function repair_private.snapshot(j repair_private.jobs) returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object('business',(select data from repair_private.business),'info',j.info,'calculation',repair_private.calc(j.lines),'estimate_number',j.number,'job_number',j.job_number,'revision',j.revision,'customer_approval',j.customer_approval,'insurer_approval',j.insurer_approval);
$$;
create function repair_private.paid(j uuid) returns bigint language sql stable set search_path='' as $$
 select coalesce(sum(case kind when 'refund' then -amount_minor else amount_minor end),0)::bigint from repair_private.payments where job_id=j;
$$;
create function repair_private.bill_paid(b uuid) returns bigint language sql stable set search_path='' as $$
 select coalesce(sum(case kind when 'refund' then -amount_minor else amount_minor end),0)::bigint from repair_private.supplier_payments where bill_id=b;
$$;
-- Cumulative rounding preserves every cent across allocations, including the last allocation.
create view repair_private.cost_parts as
select a.*,b.supplier_id,b.description,b.category,b.actual_minor is not null as confirmed,
 (round(b.estimated_minor*a.cum/b.quantity)-round(b.estimated_minor*(a.cum-a.quantity)/b.quantity))::bigint as estimated_minor,
 case when b.actual_minor is null then null else (round(b.actual_minor*a.cum/b.quantity)-round(b.actual_minor*(a.cum-a.quantity)/b.quantity))::bigint end as actual_minor,
 (round(repair_private.bill_paid(b.id)*a.cum/b.quantity)-round(repair_private.bill_paid(b.id)*(a.cum-a.quantity)/b.quantity))::bigint as cash_paid_minor
from (select a.*,sum(quantity) over(partition by bill_id order by created_at,id) as cum from repair_private.allocations a) a join repair_private.bills b on b.id=a.bill_id;
create function repair_private.profit(j repair_private.jobs) returns jsonb language plpgsql stable set search_path='' as $$
declare revenue bigint:=0; tax bigint:=0; estimate bigint; cost bigint; estimated_cost bigint; credit bigint; cash bigint; invdate timestamptz; complete boolean; paid bigint:=repair_private.paid(j.id); begin
 select coalesce(sum(d.net_minor),0),coalesce(sum(d.tax_minor),0),max(d.created_at) into revenue,tax,invdate from repair_private.documents d where d.job_id=j.id and d.kind='invoice' and d.status='issued';
 select coalesce(sum(c.net_minor),0) into credit from repair_private.documents c join repair_private.documents i on i.id=c.parent_id where c.job_id=j.id and c.kind='credit' and i.status='issued';
 revenue:=revenue-credit;
 select tax-coalesce(sum(c.tax_minor),0) into tax from repair_private.documents c join repair_private.documents i on i.id=c.parent_id where c.job_id=j.id and c.kind='credit' and i.status='issued';
 select coalesce(sum(actual_minor),0),coalesce(sum(estimated_minor),0),coalesce(bool_and(confirmed),true),coalesce(sum(cash_paid_minor),0) into cost,estimated_cost,complete,cash from repair_private.cost_parts where job_id=j.id;
 select coalesce(sum(net_minor),0) into credit from repair_private.cost_credits where job_id=j.id;
 cost:=cost-credit;estimated_cost:=greatest(0,estimated_cost-credit);complete:=complete and j.costs_complete;
 estimate:=(repair_private.calc(j.lines)->>'net_minor')::bigint;
 return jsonb_build_object('id',j.id,'number',coalesce(j.job_number,j.number),'customer',j.info->>'customer_name','vehicle',j.info->>'registration','status',j.status,'invoice_date',invdate,'created_at',j.created_at,'revenue_minor',revenue,'tax_minor',tax,'direct_cost_minor',cost,'estimated_cost_minor',estimated_cost,'estimated_revenue_minor',estimate,'price_pending',(repair_private.calc(j.lines)->>'pending')::int,'estimated_profit_minor',estimate-estimated_cost,'profit_minor',revenue-cost,'margin',case when revenue<>0 then round((revenue-cost)*100.0/revenue,2) end,'markup',case when cost>0 then round((revenue-cost)*100.0/cost,2) end,'complete',complete,'collected_minor',paid,'receivable_minor',revenue+tax-paid,'cash_paid_minor',cash,'cash_movement_minor',paid-cash);
end $$;
create function repair_private.api(action text,p jsonb,request_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); jid uuid; bid uuid; sid uuid; j repair_private.jobs; b repair_private.bills; d repair_private.documents; prior repair_private.requests;
 result jsonb; cal jsonb; info jsonb; k text; perm text; reason text:=trim(coalesce(p->>'reason','')); amount bigint; tax bigint; total bigint; paid bigint; q numeric; allocated numeric; count_rows int; new_id uuid; due date; existing bigint; oldqty numeric; billflag boolean;
begin
 if uid is null or not public.current_user_is_active() or public.current_user_role() not in('administrator','insurance_officer') then raise exception 'Active staff account required' using errcode='42501';end if;
 if action in('list','document') then
  if not (repair_private.can('view_repairs') or repair_private.can('manage_repairs') or repair_private.can('view_repair_billing') or repair_private.can('manage_repair_payments')) then raise exception 'Repair access denied' using errcode='42501';end if;
 elsif action in('shop_list','attachment_get') then
  if not(repair_private.can('manage_shop_costs') or repair_private.can('view_job_profit')) then raise exception 'Shop access denied' using errcode='42501';end if;
 elsif action in('report','report_export') then
  if not repair_private.can('view_job_profit') or (action='report_export' and not repair_private.can('export_repair_reports')) then raise exception 'Profit/report access denied' using errcode='42501';end if;
 else
  perm:=case when action in('supplier_save','bill_save','bill_confirm','allocation','cost_credit','supplier_payment','supplier_refund','costs_complete','attachment_link') then 'manage_shop_costs'
   when action in('invoice_issue','invoice_void','customer_credit','payment','refund') then 'manage_repair_payments'
   when action='business_save' then 'manage_system_settings' else 'manage_repairs' end;
  if not repair_private.can(perm) then raise exception 'Permission required: %',perm using errcode='42501';end if;
 end if;
 billflag:=repair_private.can('view_repair_billing') or repair_private.can('manage_repair_payments');
 if action='list' then
  return jsonb_build_object('business',(select to_jsonb(v) from repair_private.business v),'jobs',(select coalesce(jsonb_agg(to_jsonb(v)-'costs_complete' order by v.updated_at desc),'[]') from repair_private.jobs v),
   'documents',(select coalesce(jsonb_agg(to_jsonb(v) order by v.created_at desc),'[]') from repair_private.documents v where billflag or v.kind='estimate'),
   'payments',(select coalesce(jsonb_agg(to_jsonb(v) order by v.created_at desc),'[]') from repair_private.payments v where billflag),
   'events',(select coalesce(jsonb_agg(to_jsonb(v) order by v.created_at desc),'[]') from repair_private.events v where v.action in('save','send','approve','reject','start','complete','cancel','insurer_decision')));
 elsif action='document' then
  select * into strict d from repair_private.documents where id=(p->>'id')::uuid;
  if d.kind<>'estimate' and not billflag then raise exception 'Billing access denied';end if;
  return to_jsonb(d);
 elsif action='shop_list' then
  return jsonb_build_object('suppliers',(select coalesce(jsonb_agg(to_jsonb(v)),'[]') from repair_private.suppliers v),'bills',(select coalesce(jsonb_agg(to_jsonb(v) order by v.created_at desc),'[]') from repair_private.bills v),'allocations',(select coalesce(jsonb_agg(to_jsonb(v)),'[]') from repair_private.cost_parts v),'credits',(select coalesce(jsonb_agg(to_jsonb(v)),'[]') from repair_private.cost_credits v),'payments',(select coalesce(jsonb_agg(to_jsonb(v)),'[]') from repair_private.supplier_payments v),'jobs',(select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'number',coalesce(v.job_number,v.number),'customer',v.info->>'customer_name','vehicle',v.info->>'registration','costs_complete',v.costs_complete,'lines',v.lines)),'[]') from repair_private.jobs v));
 elsif action in('report','report_export') then
  return (select coalesce(jsonb_agg(v),'[]') from (select repair_private.profit(r) as v from repair_private.jobs r where r.status<>'cancelled') s
   where coalesce((v->>'invoice_date')::timestamptz,(v->>'created_at')::timestamptz) at time zone 'Asia/Colombo'>=coalesce(nullif(p->>'from','')::date,'1900-01-01'::date)
   and coalesce((v->>'invoice_date')::timestamptz,(v->>'created_at')::timestamptz) at time zone 'Asia/Colombo'<coalesce(nullif(p->>'to','')::date,'9998-12-31'::date)+1);
 end if;
 if request_id is null then raise exception 'Request ID required';end if;
 perform pg_advisory_xact_lock(hashtextextended('repair:'||uid::text||request_id::text,0));
 select * into prior from repair_private.requests r where r.actor=uid and r.request_id=api.request_id;
 if found then
  if prior.action<>api.action or prior.payload_hash<>md5(p::text) then raise exception 'Request key reused with different data';end if;
  return prior.response;
 end if;
 -- Financial operations serialize within this single-business module, preventing crossed job/bill lock order.
 perform pg_advisory_xact_lock(hashtextextended('tenuli-repair-finance',0));
 jid:=nullif(p->>'job_id','')::uuid;bid:=nullif(p->>'bill_id','')::uuid;
 if jid is not null then select * into strict j from repair_private.jobs where id=jid for update;end if;
 if bid is not null then select * into strict b from repair_private.bills where id=bid for update;end if;
 if length(reason)>1000 then raise exception 'Reason too long';end if;
 if action='save' then
  cal:=repair_private.calc(p->'lines');info:='{}';
  foreach k in array array['customer_name','phone','address','registration','make_model','vehicle_id','accident_date','insurance','policy_number','claim_number','valid_until','advisor','expected_date','notes'] loop
   info:=info||jsonb_build_object(k,left(coalesce(p->'info'->>k,''),case when k in('notes','address') then 1000 else 200 end));
  end loop;
  if trim(info->>'customer_name')='' or trim(info->>'registration')='' then raise exception 'Customer and vehicle registration required';end if;
  foreach k in array array['accident_date','valid_until','expected_date'] loop perform nullif(info->>k,'')::date;end loop;
  if coalesce(info->>'vehicle_id','')<>'' and not exists(select 1 from public.vehicles where id=(info->>'vehicle_id')::uuid) then raise exception 'Vehicle not found';end if;
  info:=info||jsonb_build_object('expected_customer_minor',repair_private.amount(p->'info','expected_customer_minor'),'expected_insurer_minor',repair_private.amount(p->'info','expected_insurer_minor'));
  if jid is null then
   insert into repair_private.jobs(info,lines,created_by) values(info,cal->'lines',uid) returning * into j;jid:=j.id;
  else
   if exists(select 1 from repair_private.documents where job_id=jid and kind='invoice' and status='issued') then raise exception 'Issued invoice exists; use credit or void before revising';end if;
   if j.status='cancelled' or reason='' then raise exception 'Revision reason required; cancelled jobs cannot change';end if;
   update repair_private.jobs set info=api.info,lines=cal->'lines',version=version+1,revision=revision+1,status='draft',customer_approval='pending',insurer_approval='not_requested',updated_at=now() where id=jid and version=(p->>'version')::int returning * into j;
   if not found then raise exception 'Job changed; reload before editing' using errcode='40001';end if;
  end if;
  result:=to_jsonb(j)-'costs_complete';
 elsif action in('send','approve','reject','start','complete','cancel','insurer_decision') then
  if j.id is null or j.version is distinct from (p->>'version')::int then raise exception 'Job changed; reload' using errcode='40001';end if;
  if reason='' then raise exception 'Reason / approval reference required';end if;
  if action='send' then
   if j.status<>'draft' then raise exception 'Only draft estimates can be sent';end if;
   cal:=repair_private.calc(j.lines);
   insert into repair_private.documents(job_id,number,kind,snapshot,net_minor,tax_minor,total_minor,created_by) values(jid,j.number||'-R'||j.revision,'estimate',repair_private.snapshot(j), (cal->>'net_minor')::bigint,(cal->>'tax_minor')::bigint,(cal->>'total_minor')::bigint,uid);
   j.status:='sent';
  elsif action='approve' then if j.status not in('draft','sent') then raise exception 'Estimate is not awaiting approval';end if;j.status:='approved';j.customer_approval:='approved';j.job_number:=coalesce(j.job_number,'TAC-JOB-'||nextval('repair_private.job_no'));
  elsif action='reject' then if j.status not in('draft','sent') then raise exception 'Estimate is not awaiting approval';end if;j.status:='rejected';j.customer_approval:='rejected';
  elsif action='start' then if j.status<>'approved' then raise exception 'Approve estimate first';end if;j.status:='in_progress';
  elsif action='complete' then if j.status<>'in_progress' then raise exception 'Start the job first';end if;j.status:='completed';
  elsif action='cancel' then
   if exists(select 1 from repair_private.documents where job_id=jid and kind='invoice' and status='issued') or repair_private.paid(jid)<>0 or exists(select 1 from repair_private.cost_parts where job_id=jid and (not confirmed or cash_paid_minor<>0)) or coalesce((select sum(actual_minor) from repair_private.cost_parts where job_id=jid),0)<>coalesce((select sum(net_minor) from repair_private.cost_credits where job_id=jid),0) then raise exception 'Settle/refund billing, credit allocated costs and settle supplier cash before cancellation';end if;j.status:='cancelled';
  else if j.status='cancelled' or p->>'decision' not in('pending','approved','rejected','not_requested') or p->>'decision' is null then raise exception 'Invalid insurer decision';end if;j.insurer_approval:=p->>'decision';end if;
  update repair_private.jobs set status=j.status,customer_approval=j.customer_approval,insurer_approval=j.insurer_approval,job_number=j.job_number,version=version+1,updated_at=now() where id=jid returning * into j;
  result:=to_jsonb(j)-'costs_complete';
 elsif action='invoice_issue' then
  if j.id is null or j.version is distinct from (p->>'version')::int or j.status<>'completed' or j.customer_approval<>'approved' then raise exception 'Complete the approved job and reload before invoicing';end if;
  cal:=repair_private.calc(j.lines);if (cal->>'pending')::int>0 then raise exception 'Resolve or explicitly exclude every price-pending item';end if;
  due:=(p->>'due_date')::date;if due is null then raise exception 'Due date required';end if;
  if repair_private.paid(jid)>(cal->>'total_minor')::bigint then raise exception 'Refund excess advance before issuing';end if;
  insert into repair_private.documents(job_id,number,kind,snapshot,net_minor,tax_minor,total_minor,created_by) values(jid,'TAC-INV-'||nextval('repair_private.document_no'),'invoice',repair_private.snapshot(j)||jsonb_build_object('due_date',due),(cal->>'net_minor')::bigint,(cal->>'tax_minor')::bigint,(cal->>'total_minor')::bigint,uid) returning to_jsonb(documents) into result;
 elsif action in('invoice_void','customer_credit') then
  select * into strict d from repair_private.documents where id=(p->>'document_id')::uuid and kind='invoice' and status='issued' for update;jid:=d.job_id;
  if reason='' then raise exception 'Correction reason required';end if;
  if action='invoice_void' then
   if repair_private.paid(jid)<>0 then raise exception 'Refund received money before voiding';end if;
   update repair_private.documents set status='void' where id=d.id;result:=jsonb_build_object('voided',d.id);
  else
   amount:=repair_private.amount(p,'net_minor');tax:=repair_private.amount(p,'tax_minor');
   if amount+tax<=0 or amount+coalesce((select sum(net_minor) from repair_private.documents where parent_id=d.id),0)>d.net_minor or tax+coalesce((select sum(tax_minor) from repair_private.documents where parent_id=d.id),0)>d.tax_minor then raise exception 'Credit exceeds invoice';end if;
   insert into repair_private.documents(job_id,number,kind,parent_id,snapshot,net_minor,tax_minor,total_minor,created_by) values(jid,'TAC-CR-'||nextval('repair_private.document_no'),'credit',d.id,jsonb_build_object('business',d.snapshot->'business','info',d.snapshot->'info','original_number',d.number,'reason',reason,'calculation',jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('description',reason,'category','Credit','quantity',1,'net_minor',amount,'tax_minor',tax,'unit_minor',amount)),'net_minor',amount,'tax_minor',tax,'total_minor',amount+tax,'pending',0)),amount,tax,amount+tax,uid) returning to_jsonb(documents) into result;
  end if;
 elsif action in('payment','refund') then
  if j.id is null then raise exception 'Choose a job';end if;
  amount:=repair_private.amount(p,'amount_minor');paid:=repair_private.paid(jid);
  if amount<=0 or reason='' then raise exception 'Positive amount and reason required';end if;
  if action='refund' then if amount>paid then raise exception 'Refund exceeds amount received';end if;
  else
   if j.status in('cancelled','rejected') then raise exception 'Job cannot receive payments';end if;
   select * into d from repair_private.documents where job_id=jid and kind='invoice' and status='issued';
   if found then total:=d.total_minor-coalesce((select sum(total_minor) from repair_private.documents where parent_id=d.id),0);if paid+amount>total then raise exception 'Payment exceeds balance';end if;end if;
  end if;
  insert into repair_private.payments(job_id,kind,amount_minor,payer,method,reference,reason,snapshot,created_by) values(jid,action,amount,p->>'payer',p->>'method',left(coalesce(p->>'reference',''),200),reason,repair_private.snapshot(j),uid) returning to_jsonb(payments) into result;
 elsif action='supplier_save' then
  info:='{}';foreach k in array array['name','contact','phone','address','terms'] loop info:=info||jsonb_build_object(k,left(coalesce(p->>k,''),500));end loop;
  if trim(info->>'name')='' then raise exception 'Supplier name required';end if;sid:=nullif(p->>'id','')::uuid;
  if sid is null then insert into repair_private.suppliers(data) values(info) returning id into sid;
  else update repair_private.suppliers set data=info,version=version+1 where id=sid and version=(p->>'version')::int;if not found then raise exception 'Supplier changed; reload';end if;end if;
  result:=jsonb_build_object('id',sid);
 elsif action='bill_save' then
  q:=(p->>'quantity')::numeric;if q is null or q<=0 or q>100000 or q<>round(q,3) then raise exception 'Invalid quantity';end if;
  if trim(coalesce(p->>'description',''))='' then raise exception 'Description required';end if;
  amount:=repair_private.amount(p,'estimated_minor');total:=case when p->>'actual_minor' is null then null else repair_private.amount(p,'actual_minor') end;tax:=repair_private.amount(p,'tax_minor');
  insert into repair_private.bills(supplier_id,description,category,quantity,unit,estimated_minor,actual_minor,tax_minor,reference,purchase_date,due_date,terms)
   values(nullif(p->>'supplier_id','')::uuid,left(p->>'description',300),left(coalesce(p->>'category','Parts'),100),q,left(coalesce(p->>'unit','item'),30),amount,total,tax,left(coalesce(p->>'reference',''),200),(p->>'purchase_date')::date,nullif(p->>'due_date','')::date,left(coalesce(p->>'terms',''),500)) returning to_jsonb(bills) into result;
 elsif action='bill_confirm' then
  if b.id is null or b.actual_minor is not null or b.version is distinct from (p->>'version')::int or reason='' then raise exception 'Unconfirmed bill, current version and reason required';end if;
  update repair_private.bills set actual_minor=repair_private.amount(p,'actual_minor'),tax_minor=repair_private.amount(p,'tax_minor'),version=version+1 where id=bid returning to_jsonb(bills) into result;
  update repair_private.jobs set costs_complete=false where id in(select job_id from repair_private.allocations where bill_id=bid);
 elsif action='allocation' then
  if b.id is null or j.id is null or j.status='cancelled' then raise exception 'Choose a bill and active job';end if;
  q:=(p->>'quantity')::numeric;if q is null or q<=0 or q<>round(q,3) then raise exception 'Invalid quantity';end if;
  select coalesce(sum(quantity),0) into allocated from repair_private.allocations where bill_id=bid;
  if exists(select 1 from repair_private.cost_credits where bill_id=bid and job_id is null) then raise exception 'This bill has unused-stock credits. Reverse the remaining unused stock on this bill before recording its adjusted replacement purchase';end if;
  if allocated+q>b.quantity then raise exception 'Allocation exceeds purchased quantity';end if;
  if coalesce(p->>'line_id','')<>'' and not exists(select 1 from jsonb_array_elements(j.lines) x where x->>'id'=p->>'line_id') then raise exception 'Invalid repair line';end if;
  insert into repair_private.allocations(bill_id,job_id,line_id,quantity) values(bid,jid,nullif(p->>'line_id',''),q) returning to_jsonb(allocations) into result;
  update repair_private.jobs set costs_complete=false where id=jid;
 elsif action='cost_credit' then
  if b.id is null or b.actual_minor is null or reason='' then raise exception 'Confirmed bill and reason required';end if;
  amount:=repair_private.amount(p,'net_minor');tax:=repair_private.amount(p,'tax_minor');q:=coalesce((p->>'quantity')::numeric,0);
  if amount<=0 or q<0 or q<>round(q,3) then raise exception 'Invalid credit amount / quantity';end if;
  select coalesce(sum(net_minor),0) into existing from repair_private.cost_credits where bill_id=bid;
  if existing+amount>b.actual_minor or tax+coalesce((select sum(tax_minor) from repair_private.cost_credits where bill_id=bid),0)>b.tax_minor then raise exception 'Credit exceeds purchase';end if;
  if jid is not null then
   select actual_minor,quantity into total,oldqty from repair_private.cost_parts where bill_id=bid and job_id=jid;
   if not found or amount+coalesce((select sum(net_minor) from repair_private.cost_credits where bill_id=bid and job_id=jid),0)>total or q+coalesce((select sum(quantity) from repair_private.cost_credits where bill_id=bid and job_id=jid),0)>oldqty then raise exception 'Credit exceeds job allocation';end if;
  else
   total:=b.actual_minor-coalesce((select sum(actual_minor) from repair_private.cost_parts where bill_id=bid),0);oldqty:=b.quantity-coalesce((select sum(quantity) from repair_private.allocations where bill_id=bid),0);
   if amount+coalesce((select sum(net_minor) from repair_private.cost_credits where bill_id=bid and job_id is null),0)>total or q+coalesce((select sum(quantity) from repair_private.cost_credits where bill_id=bid and job_id is null),0)>oldqty then raise exception 'Choose the allocated job for this credit';end if;
  end if;
  insert into repair_private.cost_credits(bill_id,job_id,net_minor,tax_minor,quantity,reason) values(bid,jid,amount,tax,q,reason) returning to_jsonb(cost_credits) into result;
 elsif action in('supplier_payment','supplier_refund') then
  if b.id is null or b.actual_minor is null or reason='' then raise exception 'Confirmed bill and reason required';end if;
  amount:=repair_private.amount(p,'amount_minor');paid:=repair_private.bill_paid(bid);total:=b.actual_minor+b.tax_minor-coalesce((select sum(net_minor+tax_minor) from repair_private.cost_credits where bill_id=bid),0);
  if amount<=0 or (action='supplier_payment' and paid+amount>total) or (action='supplier_refund' and amount>greatest(0,paid-total)) then raise exception 'Payment/refund exceeds supplier balance';end if;
  if p->>'method' not in('cash','bank','card') or p->>'method' is null then raise exception 'Payment method required';end if;
  insert into repair_private.supplier_payments(bill_id,kind,amount_minor,method,reference,reason) values(bid,case action when 'supplier_payment' then 'payment' else 'refund' end,amount,p->>'method',left(coalesce(p->>'reference',''),200),reason) returning to_jsonb(supplier_payments) into result;
 elsif action='costs_complete' then
  if j.id is null or reason='' or exists(select 1 from repair_private.cost_parts where job_id=jid and not confirmed) then raise exception 'Confirm all costs and enter a reason';end if;
  update repair_private.jobs set costs_complete=true where id=jid;result:=jsonb_build_object('saved',true);
 elsif action='attachment_link' then
  if b.id is null or not coalesce(p->>'path','') ~ ('^'||bid::text||'/[0-9a-f-]+\.(pdf|png|jpg|webp)$') then raise exception 'Invalid attachment path';end if;
  update repair_private.bills set attachment_path=p->>'path',version=version+1 where id=bid;result:=jsonb_build_object('saved',true);
 elsif action='business_save' then
  if public.current_user_role()<>'administrator' then raise exception 'Administrator required';end if;
  info:='{}';foreach k in array array['name','address','phone','email','notes','logo'] loop info:=info||jsonb_build_object(k,coalesce(p->>k,''));end loop;
  if length(info::text)>400000 or trim(info->>'name')='' or not ((info->>'logo')='/tenuli-logo.svg' or (info->>'logo') ~ '^data:image/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$') then raise exception 'Use a name and PNG/JPEG/WebP logo smaller than 280 KB';end if;
  update repair_private.business set data=info,version=version+1 where version=(p->>'version')::int;if not found then raise exception 'Business settings changed; reload';end if;
  result:=jsonb_build_object('saved',true);
 else raise exception 'Unknown repair action';end if;
 insert into repair_private.events(job_id,actor,action,reason) values(jid,uid,action,reason);
 insert into public.audit_logs(actor_user_id,action,entity_type,entity_id,metadata) values(uid,'repair_'||action,'repair',coalesce(jid,bid,sid)::text,jsonb_build_object('reason',reason));
 insert into repair_private.requests values(uid,request_id,action,md5(p::text),result);
 return result;
end $$;
revoke all on all functions in schema repair_private from public,anon,authenticated;
grant execute on function repair_private.previous_permission_allowed_for_role(public.app_role,text),repair_private.can(text),repair_private.api(text,jsonb,uuid) to authenticated;
create function public.repair_api(p_action text,p_payload jsonb default '{}',p_request_id uuid default null) returns jsonb language sql security invoker set search_path='' as $$ select repair_private.api(p_action,p_payload,p_request_id); $$;
revoke all on function public.repair_api(text,jsonb,uuid),public.permission_allowed_for_role(public.app_role,text) from public,anon;
grant execute on function public.repair_api(text,jsonb,uuid),public.permission_allowed_for_role(public.app_role,text) to authenticated;
-- Supabase Storage is optional for local PGlite tests. Live bucket stays private.
do $$ begin if to_regclass('storage.buckets') is not null then
 insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('tenuli-shop-bills','tenuli-shop-bills',false,5242880,array['application/pdf','image/png','image/jpeg','image/webp']) on conflict(id) do nothing;
 execute $policy$create policy tenuli_bills_read on storage.objects for select to authenticated using(bucket_id='tenuli-shop-bills' and (repair_private.can('manage_shop_costs') or repair_private.can('view_job_profit')))$policy$;
 execute $policy$create policy tenuli_bills_insert on storage.objects for insert to authenticated with check(bucket_id='tenuli-shop-bills' and repair_private.can('manage_shop_costs'))$policy$;
 end if;end $$;

$tenuli_repair_sql$;
 end if;
 if to_regclass('repair_private.jobs') is null or to_regclass('repair_private.bills') is null or to_regclass('public.rental_business') is null then
  raise exception 'Module functions exist but required tables are missing. Review this installation; no changes were committed.';
 end if;
end
$tenuli_install$;
-- Tenuli Auto Care v1.11.0: simple billing; no historical balances are rewritten.
-- Run after Rentals + Repairs, or use the combined ENABLE_AUTOMART.sql installer.

select pg_advisory_xact_lock(hashtextextended('tenuli-repair-finance',0));
-- Keep legacy fields for immutable snapshots and correctly bounded reversals.
alter table repair_private.cost_credits drop constraint if exists cost_credits_net_minor_check;
alter table repair_private.cost_credits add constraint cost_credits_net_minor_check check(net_minor>=0);
alter table repair_private.cost_credits drop constraint if exists cost_credits_positive_total;
alter table repair_private.cost_credits add constraint cost_credits_positive_total check(net_minor+tax_minor>0);
create or replace function repair_private.split_credit(total bigint,remaining_net bigint,remaining_tax bigint)
returns jsonb language plpgsql immutable set search_path='' as $$
declare tax bigint;begin
 if total is null or total<=0 or remaining_net is null or remaining_tax is null or remaining_net<0 or remaining_tax<0 or total>remaining_net+remaining_tax then raise exception 'Credit exceeds remaining amount';end if;
 tax:=round(total::numeric*remaining_tax/(remaining_net+remaining_tax))::bigint;
 return jsonb_build_object('net',total-tax,'tax',tax);
end $$;
revoke all on function repair_private.split_credit(bigint,bigint,bigint) from public,anon,authenticated;
create or replace function repair_private.api(action text,p jsonb,request_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
<<repair_body>>
declare uid uuid:=auth.uid(); jid uuid; bid uuid; sid uuid; j repair_private.jobs; b repair_private.bills; d repair_private.documents; prior repair_private.requests;
 result jsonb; cal jsonb; info jsonb; k text; perm text; reason text:=trim(coalesce(p->>'reason','')); amount bigint; tax bigint; total bigint; paid bigint; q numeric; allocated numeric; count_rows int; new_id uuid; due date; existing bigint; oldqty numeric; billflag boolean; remaining_net bigint; remaining_tax bigint; split jsonb;
begin
 if uid is null or not public.current_user_is_active() or public.current_user_role() not in('administrator','insurance_officer') then raise exception 'Active staff account required' using errcode='42501';end if;
 if action in('list','document') then
  if not (repair_private.can('view_repairs') or repair_private.can('manage_repairs') or repair_private.can('view_repair_billing') or repair_private.can('manage_repair_payments')) then raise exception 'Repair access denied' using errcode='42501';end if;
 elsif action in('shop_list','attachment_get') then
  if not(repair_private.can('manage_shop_costs') or repair_private.can('view_job_profit')) then raise exception 'Shop access denied' using errcode='42501';end if;
 elsif action in('report','report_export') then
  if not repair_private.can('view_job_profit') or (action='report_export' and not repair_private.can('export_repair_reports')) then raise exception 'Profit/report access denied' using errcode='42501';end if;
 else
  perm:=case when action in('supplier_save','bill_save','bill_confirm','allocation','cost_credit','supplier_payment','supplier_refund','costs_complete','attachment_link') then 'manage_shop_costs'
   when action in('invoice_issue','invoice_void','customer_credit','payment','refund') then 'manage_repair_payments'
   when action='business_save' then 'manage_system_settings' else 'manage_repairs' end;
  if not repair_private.can(perm) then raise exception 'Permission required: %',perm using errcode='42501';end if;
 end if;
 billflag:=repair_private.can('view_repair_billing') or repair_private.can('manage_repair_payments');
 if action='list' then
  return jsonb_build_object('simple_billing',true,'business',(select to_jsonb(v) from repair_private.business v),'jobs',(select coalesce(jsonb_agg(to_jsonb(v)-'costs_complete' order by v.updated_at desc),'[]') from repair_private.jobs v),
   'documents',(select coalesce(jsonb_agg(to_jsonb(v) order by v.created_at desc),'[]') from repair_private.documents v where billflag or v.kind='estimate'),
   'payments',(select coalesce(jsonb_agg(to_jsonb(v) order by v.created_at desc),'[]') from repair_private.payments v where billflag),
   'events',(select coalesce(jsonb_agg(to_jsonb(v) order by v.created_at desc),'[]') from repair_private.events v where v.action in('save','send','approve','reject','start','complete','cancel','insurer_decision')));
 elsif action='document' then
  select * into strict d from repair_private.documents where id=(p->>'id')::uuid;
  if d.kind<>'estimate' and not billflag then raise exception 'Billing access denied';end if;
  return to_jsonb(d);
 elsif action='shop_list' then
  return jsonb_build_object('simple_billing',true,'suppliers',(select coalesce(jsonb_agg(to_jsonb(v)),'[]') from repair_private.suppliers v),'bills',(select coalesce(jsonb_agg(to_jsonb(v) order by v.created_at desc),'[]') from repair_private.bills v),'allocations',(select coalesce(jsonb_agg(to_jsonb(v)),'[]') from repair_private.cost_parts v),'credits',(select coalesce(jsonb_agg(to_jsonb(v)),'[]') from repair_private.cost_credits v),'payments',(select coalesce(jsonb_agg(to_jsonb(v)),'[]') from repair_private.supplier_payments v),'jobs',(select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'number',coalesce(v.job_number,v.number),'customer',v.info->>'customer_name','vehicle',v.info->>'registration','costs_complete',v.costs_complete,'lines',v.lines)),'[]') from repair_private.jobs v));
 elsif action in('report','report_export') then
  return (select coalesce(jsonb_agg(v),'[]') from (select repair_private.profit(r) as v from repair_private.jobs r where r.status<>'cancelled') s
   where coalesce((v->>'invoice_date')::timestamptz,(v->>'created_at')::timestamptz) at time zone 'Asia/Colombo'>=coalesce(nullif(p->>'from','')::date,'1900-01-01'::date)
   and coalesce((v->>'invoice_date')::timestamptz,(v->>'created_at')::timestamptz) at time zone 'Asia/Colombo'<coalesce(nullif(p->>'to','')::date,'9998-12-31'::date)+1);
 end if;
 if request_id is null then raise exception 'Request ID required';end if;
 perform pg_advisory_xact_lock(hashtextextended('repair:'||uid::text||request_id::text,0));
 select * into prior from repair_private.requests r where r.actor=uid and r.request_id=api.request_id;
 if found then
  if prior.action<>api.action or prior.payload_hash<>md5(p::text) then raise exception 'Request key reused with different data';end if;
  return prior.response;
 end if;
 -- Financial operations serialize within this single-business module, preventing crossed job/bill lock order.
 perform pg_advisory_xact_lock(hashtextextended('tenuli-repair-finance',0));
 jid:=nullif(p->>'job_id','')::uuid;bid:=nullif(p->>'bill_id','')::uuid;
 if jid is not null then select * into strict j from repair_private.jobs where id=jid for update;end if;
 if bid is not null then select * into strict b from repair_private.bills where id=bid for update;end if;
 if length(reason)>1000 then raise exception 'Reason too long';end if;
 if action='save' then
  if exists(select 1 from jsonb_array_elements(p->'lines') x where coalesce((x->>'tax_bps')::int,0)<>0) then
   raise exception 'Use simple pricing: reopen the estimate in the updated app before saving';end if;
  cal:=repair_private.calc((select jsonb_agg(x||jsonb_build_object('tax_bps',0)) from jsonb_array_elements(p->'lines') x));info:='{}';
  foreach k in array array['customer_name','phone','address','registration','make_model','vehicle_id','accident_date','insurance','policy_number','claim_number','valid_until','advisor','expected_date','notes'] loop
   info:=info||jsonb_build_object(k,left(coalesce(p->'info'->>k,''),case when k in('notes','address') then 1000 else 200 end));
  end loop;
  if trim(info->>'customer_name')='' or trim(info->>'registration')='' then raise exception 'Customer and vehicle registration required';end if;
  foreach k in array array['accident_date','valid_until','expected_date'] loop perform nullif(info->>k,'')::date;end loop;
  if coalesce(info->>'vehicle_id','')<>'' and not exists(select 1 from public.vehicles where id=(info->>'vehicle_id')::uuid) then raise exception 'Vehicle not found';end if;
  info:=info||jsonb_build_object('expected_customer_minor',repair_private.amount(jsonb_build_object('expected_customer_minor',coalesce(p->'info'->>'expected_customer_minor','0')),'expected_customer_minor'),'expected_insurer_minor',repair_private.amount(jsonb_build_object('expected_insurer_minor',coalesce(p->'info'->>'expected_insurer_minor','0')),'expected_insurer_minor'));
  if jid is null then
   insert into repair_private.jobs(info,lines,created_by) values(info,cal->'lines',uid) returning * into j;jid:=j.id;
  else
   if exists(select 1 from repair_private.documents where job_id=jid and kind='invoice' and status='issued') then raise exception 'Issued invoice exists; use credit or void before revising';end if;
   if j.status='cancelled' or reason='' then raise exception 'Revision reason required; cancelled jobs cannot change';end if;
   update repair_private.jobs set info=repair_body.info,lines=cal->'lines',version=version+1,revision=revision+1,status='draft',customer_approval='pending',insurer_approval='not_requested',updated_at=now() where id=jid and version=(p->>'version')::int returning * into j;
   if not found then raise exception 'Job changed; reload before editing' using errcode='40001';end if;
  end if;
  result:=to_jsonb(j)-'costs_complete';
 elsif action in('send','approve','reject','start','complete','cancel','insurer_decision') then
  if j.id is null or j.version is distinct from (p->>'version')::int then raise exception 'Job changed; reload' using errcode='40001';end if;
  if reason='' then raise exception 'Reason / approval reference required';end if;
  if action='send' then
   if j.status<>'draft' then raise exception 'Only draft estimates can be sent';end if;
   cal:=repair_private.calc(j.lines);
   insert into repair_private.documents(job_id,number,kind,snapshot,net_minor,tax_minor,total_minor,created_by) values(jid,j.number||'-R'||j.revision,'estimate',repair_private.snapshot(j), (cal->>'net_minor')::bigint,(cal->>'tax_minor')::bigint,(cal->>'total_minor')::bigint,uid);
   j.status:='sent';
  elsif action='approve' then if j.status not in('draft','sent') then raise exception 'Estimate is not awaiting approval';end if;j.status:='approved';j.customer_approval:='approved';j.job_number:=coalesce(j.job_number,'TAC-JOB-'||nextval('repair_private.job_no'));
  elsif action='reject' then if j.status not in('draft','sent') then raise exception 'Estimate is not awaiting approval';end if;j.status:='rejected';j.customer_approval:='rejected';
  elsif action='start' then if j.status<>'approved' then raise exception 'Approve estimate first';end if;j.status:='in_progress';
  elsif action='complete' then if j.status<>'in_progress' then raise exception 'Start the job first';end if;j.status:='completed';
  elsif action='cancel' then
   if exists(select 1 from repair_private.documents where job_id=jid and kind='invoice' and status='issued') or repair_private.paid(jid)<>0 or exists(select 1 from repair_private.cost_parts where job_id=jid and (not confirmed or cash_paid_minor<>0)) or coalesce((select sum(actual_minor) from repair_private.cost_parts where job_id=jid),0)<>coalesce((select sum(net_minor) from repair_private.cost_credits where job_id=jid),0) then raise exception 'Settle/refund billing, credit allocated costs and settle supplier cash before cancellation';end if;j.status:='cancelled';
  else if j.status='cancelled' or p->>'decision' not in('pending','approved','rejected','not_requested') or p->>'decision' is null then raise exception 'Invalid insurer decision';end if;j.insurer_approval:=p->>'decision';end if;
  update repair_private.jobs set status=j.status,customer_approval=j.customer_approval,insurer_approval=j.insurer_approval,job_number=j.job_number,version=version+1,updated_at=now() where id=jid returning * into j;
  result:=to_jsonb(j)-'costs_complete';
 elsif action='invoice_issue' then
  if j.id is null or j.version is distinct from (p->>'version')::int or j.status<>'completed' or j.customer_approval<>'approved' then raise exception 'Complete the approved job and reload before invoicing';end if;
  cal:=repair_private.calc(j.lines);if (cal->>'pending')::int>0 then raise exception 'Resolve or explicitly exclude every price-pending item';end if;
  if (cal->>'tax_minor')::bigint<>0 then raise exception 'Revise this older estimate using simple pricing, then approve and complete it before issuing a new invoice';end if;
  due:=(p->>'due_date')::date;if due is null then raise exception 'Due date required';end if;
  if repair_private.paid(jid)>(cal->>'total_minor')::bigint then raise exception 'Refund excess advance before issuing';end if;
  insert into repair_private.documents(job_id,number,kind,snapshot,net_minor,tax_minor,total_minor,created_by) values(jid,'TAC-INV-'||nextval('repair_private.document_no'),'invoice',repair_private.snapshot(j)||jsonb_build_object('due_date',due),(cal->>'net_minor')::bigint,(cal->>'tax_minor')::bigint,(cal->>'total_minor')::bigint,uid) returning to_jsonb(documents) into result;
 elsif action in('invoice_void','customer_credit') then
  select * into strict d from repair_private.documents where id=(p->>'document_id')::uuid and kind='invoice' and status='issued' for update;jid:=d.job_id;
  if reason='' then raise exception 'Correction reason required';end if;
  if action='invoice_void' then
   if repair_private.paid(jid)<>0 then raise exception 'Refund received money before voiding';end if;
   update repair_private.documents set status='void' where id=d.id;result:=jsonb_build_object('voided',d.id);
  else
   if p ? 'amount_minor' then
    select d.net_minor-coalesce(sum(net_minor),0),d.tax_minor-coalesce(sum(tax_minor),0) into remaining_net,remaining_tax from repair_private.documents where parent_id=d.id;
    split:=repair_private.split_credit(repair_private.amount(p,'amount_minor'),remaining_net,remaining_tax);
    amount:=(split->>'net')::bigint;tax:=(split->>'tax')::bigint;
   else amount:=repair_private.amount(p,'net_minor');tax:=repair_private.amount(p,'tax_minor');end if;
   if amount+tax<=0 or amount+coalesce((select sum(net_minor) from repair_private.documents where parent_id=d.id),0)>d.net_minor or tax+coalesce((select sum(tax_minor) from repair_private.documents where parent_id=d.id),0)>d.tax_minor then raise exception 'Credit exceeds invoice';end if;
   insert into repair_private.documents(job_id,number,kind,parent_id,snapshot,net_minor,tax_minor,total_minor,created_by) values(jid,'TAC-CR-'||nextval('repair_private.document_no'),'credit',d.id,jsonb_build_object('business',d.snapshot->'business','info',d.snapshot->'info','original_number',d.number,'reason',reason,'calculation',jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('description',reason,'category','Credit','quantity',1,'net_minor',amount,'tax_minor',tax,'unit_minor',amount)),'net_minor',amount,'tax_minor',tax,'total_minor',amount+tax,'pending',0)),amount,tax,amount+tax,uid) returning to_jsonb(documents) into result;
  end if;
 elsif action in('payment','refund') then
  if j.id is null then raise exception 'Choose a job';end if;
  amount:=repair_private.amount(p,'amount_minor');paid:=repair_private.paid(jid);
  if amount<=0 or reason='' then raise exception 'Positive amount and reason required';end if;
  if action='refund' then if amount>paid then raise exception 'Refund exceeds amount received';end if;
  else
   if j.status in('cancelled','rejected') then raise exception 'Job cannot receive payments';end if;
   select * into d from repair_private.documents where job_id=jid and kind='invoice' and status='issued';
   if found then total:=d.total_minor-coalesce((select sum(total_minor) from repair_private.documents where parent_id=d.id),0);if paid+amount>total then raise exception 'Payment exceeds balance';end if;end if;
  end if;
  insert into repair_private.payments(job_id,kind,amount_minor,payer,method,reference,reason,snapshot,created_by) values(jid,action,amount,p->>'payer',p->>'method',left(coalesce(p->>'reference',''),200),reason,repair_private.snapshot(j),uid) returning to_jsonb(payments) into result;
 elsif action='supplier_save' then
  info:='{}';foreach k in array array['name','contact','phone','address','terms'] loop info:=info||jsonb_build_object(k,left(coalesce(p->>k,''),500));end loop;
  if trim(info->>'name')='' then raise exception 'Supplier name required';end if;sid:=nullif(p->>'id','')::uuid;
  if sid is null then insert into repair_private.suppliers(data) values(info) returning id into sid;
  else update repair_private.suppliers set data=info,version=version+1 where id=sid and version=(p->>'version')::int;if not found then raise exception 'Supplier changed; reload';end if;end if;
  result:=jsonb_build_object('id',sid);
 elsif action='bill_save' then
  q:=(p->>'quantity')::numeric;if q is null or q<=0 or q>100000 or q<>round(q,3) then raise exception 'Invalid quantity';end if;
  if trim(coalesce(p->>'description',''))='' then raise exception 'Description required';end if;
  amount:=repair_private.amount(p,'estimated_minor');total:=case when p->>'actual_minor' is null then null else repair_private.amount(p,'actual_minor') end;tax:=0;
  if coalesce((p->>'tax_minor')::bigint,0)<>0 then raise exception 'Use simple pricing: record the full shop cost as one amount';end if;
  insert into repair_private.bills(supplier_id,description,category,quantity,unit,estimated_minor,actual_minor,tax_minor,reference,purchase_date,due_date,terms)
   values(nullif(p->>'supplier_id','')::uuid,left(p->>'description',300),left(coalesce(p->>'category','Parts'),100),q,left(coalesce(p->>'unit','item'),30),amount,total,tax,left(coalesce(p->>'reference',''),200),(p->>'purchase_date')::date,nullif(p->>'due_date','')::date,left(coalesce(p->>'terms',''),500)) returning to_jsonb(bills) into result;
 elsif action='bill_confirm' then
  if b.id is null or b.actual_minor is not null or b.version is distinct from (p->>'version')::int or reason='' then raise exception 'Unconfirmed bill, current version and reason required';end if;
  if p ? 'amount_minor' then
   total:=repair_private.amount(p,'amount_minor');tax:=b.tax_minor;amount:=total-tax;
   if amount<0 then raise exception 'Confirmed cost is below the original adjustment; review this historical bill';end if;
  else
   amount:=repair_private.amount(p,'actual_minor');tax:=b.tax_minor;
   if coalesce((p->>'tax_minor')::bigint,0)<>tax then raise exception 'Original bill adjustment must be preserved';end if;
  end if;
  update repair_private.bills set actual_minor=amount,tax_minor=tax,version=version+1 where id=bid returning to_jsonb(bills) into result;
  update repair_private.jobs set costs_complete=false where id in(select job_id from repair_private.allocations where bill_id=bid);
 elsif action='allocation' then
  if b.id is null or j.id is null or j.status='cancelled' then raise exception 'Choose a bill and active job';end if;
  q:=(p->>'quantity')::numeric;if q is null or q<=0 or q<>round(q,3) then raise exception 'Invalid quantity';end if;
  select coalesce(sum(quantity),0) into allocated from repair_private.allocations where bill_id=bid;
  if exists(select 1 from repair_private.cost_credits where bill_id=bid and job_id is null) then raise exception 'This bill has unused-stock credits. Reverse the remaining unused stock on this bill before recording its adjusted replacement purchase';end if;
  if allocated+q>b.quantity then raise exception 'Allocation exceeds purchased quantity';end if;
  if coalesce(p->>'line_id','')<>'' and not exists(select 1 from jsonb_array_elements(j.lines) x where x->>'id'=p->>'line_id') then raise exception 'Invalid repair line';end if;
  insert into repair_private.allocations(bill_id,job_id,line_id,quantity) values(bid,jid,nullif(p->>'line_id',''),q) returning to_jsonb(allocations) into result;
  update repair_private.jobs set costs_complete=false where id=jid;
 elsif action='cost_credit' then
  if b.id is null or b.actual_minor is null or reason='' then raise exception 'Confirmed bill and reason required';end if;
  if p ? 'amount_minor' then
   if jid is not null then
    select cp.actual_minor into remaining_net from repair_private.cost_parts cp where cp.bill_id=bid and cp.job_id=jid;
    if not found then raise exception 'Choose a job allocated to this bill';end if;
    select (round(b.tax_minor*a.cum/b.quantity)-round(b.tax_minor*(a.cum-a.quantity)/b.quantity))::bigint into remaining_tax
    from (select z.*,sum(quantity) over(order by created_at,id) as cum from repair_private.allocations z where z.bill_id=bid) a where a.job_id=jid;
   else
    select b.actual_minor-coalesce(sum(actual_minor),0) into remaining_net from repair_private.cost_parts where bill_id=bid;
    select b.tax_minor-round(b.tax_minor*coalesce(sum(quantity),0)/b.quantity)::bigint into remaining_tax from repair_private.allocations where bill_id=bid;
   end if;
   select remaining_net-coalesce(sum(net_minor),0),remaining_tax-coalesce(sum(tax_minor),0) into remaining_net,remaining_tax from repair_private.cost_credits where bill_id=bid and job_id is not distinct from jid;
   split:=repair_private.split_credit(repair_private.amount(p,'amount_minor'),remaining_net,remaining_tax);
   amount:=(split->>'net')::bigint;tax:=(split->>'tax')::bigint;
  else amount:=repair_private.amount(p,'net_minor');tax:=repair_private.amount(p,'tax_minor');end if;
  q:=coalesce((p->>'quantity')::numeric,0);
  if amount+tax<=0 or q<0 or q<>round(q,3) then raise exception 'Invalid credit amount / quantity';end if;
  select coalesce(sum(net_minor),0) into existing from repair_private.cost_credits where bill_id=bid;
  if existing+amount>b.actual_minor or tax+coalesce((select sum(tax_minor) from repair_private.cost_credits where bill_id=bid),0)>b.tax_minor then raise exception 'Credit exceeds purchase';end if;
  if jid is not null then
   select actual_minor,quantity into total,oldqty from repair_private.cost_parts where bill_id=bid and job_id=jid;
   if not found or amount+coalesce((select sum(net_minor) from repair_private.cost_credits where bill_id=bid and job_id=jid),0)>total or q+coalesce((select sum(quantity) from repair_private.cost_credits where bill_id=bid and job_id=jid),0)>oldqty then raise exception 'Credit exceeds job allocation';end if;
  else
   total:=b.actual_minor-coalesce((select sum(actual_minor) from repair_private.cost_parts where bill_id=bid),0);oldqty:=b.quantity-coalesce((select sum(quantity) from repair_private.allocations where bill_id=bid),0);
   if amount+coalesce((select sum(net_minor) from repair_private.cost_credits where bill_id=bid and job_id is null),0)>total or q+coalesce((select sum(quantity) from repair_private.cost_credits where bill_id=bid and job_id is null),0)>oldqty then raise exception 'Choose the allocated job for this credit';end if;
  end if;
  insert into repair_private.cost_credits(bill_id,job_id,net_minor,tax_minor,quantity,reason) values(bid,jid,amount,tax,q,reason) returning to_jsonb(cost_credits) into result;
 elsif action in('supplier_payment','supplier_refund') then
  if b.id is null or b.actual_minor is null or reason='' then raise exception 'Confirmed bill and reason required';end if;
  amount:=repair_private.amount(p,'amount_minor');paid:=repair_private.bill_paid(bid);total:=b.actual_minor+b.tax_minor-coalesce((select sum(net_minor+tax_minor) from repair_private.cost_credits where bill_id=bid),0);
  if amount<=0 or (action='supplier_payment' and paid+amount>total) or (action='supplier_refund' and amount>greatest(0,paid-total)) then raise exception 'Payment/refund exceeds supplier balance';end if;
  if p->>'method' not in('cash','bank','card') or p->>'method' is null then raise exception 'Payment method required';end if;
  insert into repair_private.supplier_payments(bill_id,kind,amount_minor,method,reference,reason) values(bid,case action when 'supplier_payment' then 'payment' else 'refund' end,amount,p->>'method',left(coalesce(p->>'reference',''),200),reason) returning to_jsonb(supplier_payments) into result;
 elsif action='costs_complete' then
  if j.id is null or reason='' or exists(select 1 from repair_private.cost_parts where job_id=jid and not confirmed) then raise exception 'Confirm all costs and enter a reason';end if;
  update repair_private.jobs set costs_complete=true where id=jid;result:=jsonb_build_object('saved',true);
 elsif action='attachment_link' then
  if b.id is null or not coalesce(p->>'path','') ~ ('^'||bid::text||'/[0-9a-f-]+\.(pdf|png|jpg|webp)$') then raise exception 'Invalid attachment path';end if;
  update repair_private.bills set attachment_path=p->>'path',version=version+1 where id=bid;result:=jsonb_build_object('saved',true);
 elsif action='business_save' then
  if public.current_user_role()<>'administrator' then raise exception 'Administrator required';end if;
  info:='{}';foreach k in array array['name','address','phone','email','notes','logo'] loop info:=info||jsonb_build_object(k,coalesce(p->>k,''));end loop;
  if length(info::text)>400000 or trim(info->>'name')='' or not ((info->>'logo')='/tenuli-logo.svg' or (info->>'logo') ~ '^data:image/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$') then raise exception 'Use a name and PNG/JPEG/WebP logo smaller than 280 KB';end if;
  update repair_private.business set data=info,version=version+1 where version=(p->>'version')::int;if not found then raise exception 'Business settings changed; reload';end if;
  result:=jsonb_build_object('saved',true);
 else raise exception 'Unknown repair action';end if;
 insert into repair_private.events(job_id,actor,action,reason) values(jid,uid,action,reason);
 insert into public.audit_logs(actor_user_id,action,entity_type,entity_id,metadata) values(uid,'repair_'||action,'repair',coalesce(jid,bid,sid)::text,jsonb_build_object('reason',reason));
 insert into repair_private.requests values(uid,request_id,action,md5(p::text),result);
 return result;
end $$;

create or replace function rental_private.api(p_action text,p_payload jsonb,p_request_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
#variable_conflict use_variable
declare uid uuid:=auth.uid(); b public.rental_bookings; inv public.rental_invoices; item jsonb; result jsonb; prior rental_private.requests;
 id uuid; v uuid; customer uuid; count_rows integer; quote jsonb; n bigint; amount bigint; paid bigint; deposit bigint; current_total bigint; ledger_id uuid;
 can_rent boolean; can_bill boolean; need_permission text; desired text; old_status text;
begin
 if uid is null or not public.current_user_is_active() then raise exception 'Active authenticated account required' using errcode='42501'; end if;
 can_rent:=rental_private.staff('view_rentals') or rental_private.staff('manage_rentals');
 can_bill:=rental_private.staff('view_billing') or rental_private.staff('manage_billing') or rental_private.staff('refund_payments');
 if p_action='list' then
  if not can_rent and not can_bill then
   if not public.has_permission('view_own_rentals') then raise exception 'Rental access denied' using errcode='42501'; end if;
   return jsonb_build_object('owner_only',true,'bookings',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'vehicle_id',r.vehicle_id,'pickup_at',r.pickup_at,'return_at',r.return_at,'status',r.status,'version',r.version)) from public.rental_bookings r join public.vehicles v on v.id=r.vehicle_id where v.user_id=uid),'[]'::jsonb),'customers','[]'::jsonb,'invoices','[]'::jsonb,'ledger','[]'::jsonb,'allocations','[]'::jsonb);
  end if;
  return jsonb_build_object('owner_only',false,
   'customers',case when can_rent then coalesce((select jsonb_agg(c order by c.name) from public.rental_customers c),'[]'::jsonb) else '[]'::jsonb end,
   'bookings',case when can_rent or can_bill then coalesce((select jsonb_agg(r order by r.pickup_at desc) from public.rental_bookings r),'[]'::jsonb) else '[]'::jsonb end,
   'invoices',case when can_bill then coalesce((select jsonb_agg(i order by i.issued_at desc) from public.rental_invoices i),'[]'::jsonb) else '[]'::jsonb end,
   'ledger',case when can_bill then coalesce((select jsonb_agg(l order by l.created_at desc) from public.rental_ledger l),'[]'::jsonb) else '[]'::jsonb end,
   'allocations',case when can_bill then coalesce((select jsonb_agg(a) from public.rental_allocations a),'[]'::jsonb) else '[]'::jsonb end,
   'business',(select to_jsonb(x) from public.rental_business x where x.id));
 end if;
 if p_action='quote' then
  if not (can_rent or can_bill) then raise exception 'Quote access denied' using errcode='42501'; end if;
  select * into strict b from public.rental_bookings where rental_bookings.id=(p_payload->>'id')::uuid;
  return rental_private.quote(b);
 end if;
 need_permission:=case
 when p_action in ('customer_save','booking_save','confirm','checkout','return','cancel','extend') then 'manage_rentals'
 when p_action in ('invoice_issue','charges_update','payment','deposit','deposit_apply') then 'manage_billing'
 when p_action in ('refund','deposit_refund','invoice_void') then 'refund_payments'
 when p_action='business_save' then 'manage_system_settings' else null end;
 if need_permission is null or not rental_private.staff(need_permission) then raise exception 'Operation not permitted' using errcode='42501'; end if;
 if p_request_id is null then raise exception 'Idempotency request ID required'; end if;
 perform pg_advisory_xact_lock(hashtextextended(uid::text||p_request_id::text,0));
 select * into prior from rental_private.requests where actor=uid and request_id=p_request_id;
 if found then
  if prior.action<>p_action or prior.payload_hash<>md5(p_payload::text) then raise exception 'Request ID reused with different content'; end if;
  return prior.response;
 end if;
 id:=nullif(p_payload->>'id','')::uuid;
 if p_action='customer_save' then
  if id is null then
   insert into public.rental_customers(name,phone,email,address,identity_reference,licence_reference)
   values(trim(p_payload->>'name'),coalesce(p_payload->>'phone',''),coalesce(p_payload->>'email',''),coalesce(p_payload->>'address',''),coalesce(p_payload->>'identity_reference',''),coalesce(p_payload->>'licence_reference','')) returning rental_customers.id into id;
  else
   update public.rental_customers set name=trim(p_payload->>'name'),phone=coalesce(p_payload->>'phone',''),email=coalesce(p_payload->>'email',''),address=coalesce(p_payload->>'address',''),identity_reference=coalesce(p_payload->>'identity_reference',''),licence_reference=coalesce(p_payload->>'licence_reference',''),version=version+1 where rental_customers.id=id and version=(p_payload->>'version')::integer;
   get diagnostics count_rows=row_count; if count_rows<>1 then raise exception 'Customer changed. Reload before editing' using errcode='40001'; end if;
  end if;
  result:=jsonb_build_object('id',id);
 elsif p_action='business_save' then
  if public.current_user_role()<>'administrator' then raise exception 'Administrator required'; end if;
  update public.rental_business set name=p_payload->>'name',address=coalesce(p_payload->>'address',''),phone=coalesce(p_payload->>'phone',''),notes=coalesce(p_payload->>'notes',''),version=version+1 where version=(p_payload->>'version')::integer;
  get diagnostics count_rows=row_count; if count_rows<>1 then raise exception 'Business settings changed. Reload' using errcode='40001'; end if;
  result:=jsonb_build_object('saved',true);
 elsif p_action='booking_save' then
  if coalesce((p_payload->>'tax_bps')::int,0)<>0 then raise exception 'Use simple pricing in the updated app';end if;
  v:=(p_payload->>'vehicle_id')::uuid; customer:=(p_payload->>'customer_id')::uuid;
  if not exists(select 1 from public.vehicles where vehicles.id=v and is_active) then raise exception 'Choose an active vehicle'; end if;
  if id is not null then
   select * into strict b from public.rental_bookings where rental_bookings.id=id for update;
   if b.version is distinct from (p_payload->>'version')::integer then raise exception 'Booking changed. Reload' using errcode='40001'; end if;
   if b.status<>'draft' then raise exception 'Only draft terms can be edited. Use extension for confirmed/active bookings'; end if;
  end if;
  insert into public.rental_bookings as r(id,vehicle_id,customer_id,pickup_at,return_at,rate_plan,rate_minor,included_km,excess_rate_minor,grace_minutes,extras,discount_minor,tax_bps,agreement_ref,notes,created_by)
  values(coalesce(id,gen_random_uuid()),v,customer,(p_payload->>'pickup_at')::timestamptz,(p_payload->>'return_at')::timestamptz,coalesce(p_payload->>'rate_plan','daily'),(p_payload->>'rate_minor')::bigint,coalesce((p_payload->>'included_km')::numeric,0),coalesce((p_payload->>'excess_rate_minor')::bigint,0),coalesce((p_payload->>'grace_minutes')::integer,0),coalesce(p_payload->'extras','[]'),coalesce((p_payload->>'discount_minor')::bigint,0),coalesce((p_payload->>'tax_bps')::integer,0),coalesce(p_payload->>'agreement_ref',''),coalesce(p_payload->>'notes',''),uid)
  on conflict on constraint rental_bookings_pkey do update set vehicle_id=excluded.vehicle_id,customer_id=excluded.customer_id,pickup_at=excluded.pickup_at,return_at=excluded.return_at,rate_plan=excluded.rate_plan,rate_minor=excluded.rate_minor,included_km=excluded.included_km,excess_rate_minor=excluded.excess_rate_minor,grace_minutes=excluded.grace_minutes,extras=excluded.extras,discount_minor=excluded.discount_minor,tax_bps=excluded.tax_bps,agreement_ref=excluded.agreement_ref,notes=excluded.notes,version=r.version+1,updated_at=now()
  returning * into b;
  perform rental_private.quote(b); id:=b.id; result:=to_jsonb(b);
 else
  -- Every booking/financial mutation serializes on the same booking row.
  if p_action='invoice_void' then
   select booking_id into strict id from public.rental_invoices where rental_invoices.id=(p_payload->>'invoice_id')::uuid;
  end if;
  select * into strict b from public.rental_bookings where rental_bookings.id=id for update;
  if p_action in ('confirm','checkout','return','cancel','extend') then
   if b.version is distinct from (p_payload->>'version')::integer then raise exception 'Booking changed. Reload' using errcode='40001'; end if;
   old_status:=b.status;
   if p_action='confirm' then
    if b.status<>'draft' then raise exception 'Only draft bookings can be confirmed'; end if; b.status:='confirmed';
   elsif p_action='checkout' then
    if b.status<>'confirmed' then raise exception 'Confirm before checkout'; end if;
    b.odometer_out:=(p_payload->>'odometer_out')::numeric; if b.odometer_out is null or b.odometer_out<0 then raise exception 'Valid checkout odometer required'; end if;
    b.status:='active';
   elsif p_action='return' then
    if b.status<>'active' then raise exception 'Only active rentals can be returned'; end if;
    b.odometer_in:=(p_payload->>'odometer_in')::numeric;
    b.actual_return_at:=(p_payload->>'actual_return_at')::timestamptz;
    if b.odometer_in is null or b.odometer_in<b.odometer_out or b.actual_return_at is null or b.actual_return_at<=b.pickup_at then raise exception 'Invalid return time or odometer'; end if;
    b.status:='completed';
   elsif p_action='cancel' then
    if b.status not in ('draft','confirmed') then raise exception 'Only draft or confirmed rentals can be cancelled'; end if;
    if length(trim(coalesce(p_payload->>'reason','')))=0 then raise exception 'Cancellation reason required'; end if;
    b.status:='cancelled';
   elsif p_action='extend' then
    if b.status not in ('confirmed','active') then raise exception 'Cannot extend this booking'; end if;
    if (p_payload->>'return_at')::timestamptz<=b.return_at then raise exception 'Extension must be later'; end if;
    b.return_at:=(p_payload->>'return_at')::timestamptz;
   end if;
   if b.status in ('confirmed','active') then
    perform 1 from public.vehicles where vehicles.id=b.vehicle_id and is_active for update;
    if not found then raise exception 'Vehicle is inactive or unavailable'; end if;
    perform pg_advisory_xact_lock(hashtextextended(b.vehicle_id::text,1));
    if exists(select 1 from public.rental_bookings r where r.vehicle_id=b.vehicle_id and r.id<>b.id and r.status in ('confirmed','active') and
     (tstzrange(r.pickup_at,r.return_at,'[)') && tstzrange(b.pickup_at,b.return_at,'[)') or (r.status='active' and (r.return_at<now() or p_action='checkout')))) then raise exception 'Vehicle unavailable: overlapping booking or unreturned rental' using errcode='23P01'; end if;
   end if;
   perform rental_private.quote(b);
   update public.rental_bookings set status=b.status,return_at=b.return_at,actual_return_at=b.actual_return_at,odometer_out=b.odometer_out,odometer_in=b.odometer_in,version=version+1,updated_at=now() where rental_bookings.id=b.id returning * into b;
   result:=to_jsonb(b);
  elsif p_action='charges_update' then
   if b.version is distinct from (p_payload->>'version')::integer then raise exception 'Booking changed. Reload' using errcode='40001'; end if;
   if b.status<>'completed' or exists(select 1 from public.rental_invoices where booking_id=b.id and status='issued') then raise exception 'Charges can be adjusted after return and before issuing an invoice'; end if;
   if length(trim(coalesce(p_payload->>'reason','')))=0 then raise exception 'Adjustment reason required'; end if;
   if coalesce((p_payload->>'tax_bps')::int,0)<>0 then raise exception 'Use simple pricing in the updated app';end if;
   b.extras:=coalesce(p_payload->'extras',b.extras);b.discount_minor:=coalesce((p_payload->>'discount_minor')::bigint,b.discount_minor);b.tax_bps:=0;
   perform rental_private.quote(b);
   update public.rental_bookings set extras=b.extras,discount_minor=b.discount_minor,tax_bps=b.tax_bps,version=version+1,updated_at=now() where rental_bookings.id=b.id returning * into b;
   result:=to_jsonb(b);
  elsif p_action='invoice_issue' then
   if b.version is distinct from (p_payload->>'version')::integer then raise exception 'Booking changed. Reopen the quote' using errcode='40001'; end if;
   if b.status<>'completed' then raise exception 'Record return before issuing the final invoice'; end if;
   if exists(select 1 from public.rental_invoices where booking_id=b.id and status='issued') then raise exception 'An issued invoice already exists'; end if;
   if b.tax_bps<>0 then raise exception 'Use Adjust final charges to review this older booking with simple pricing before invoicing';end if;
   quote:=rental_private.quote(b); n:=nextval('rental_private.invoice_number');
   insert into public.rental_invoices(booking_id,number,due_date,total_minor,snapshot,created_by)
   values(b.id,'INV-'||to_char(now() at time zone 'Asia/Colombo','YYYY')||'-'||lpad(n::text,greatest(6,length(n::text)),'0'),(p_payload->>'due_date')::date,(quote->>'total_minor')::bigint,
   jsonb_build_object('booking',to_jsonb(b),'calculation',quote,'customer',(select jsonb_build_object('name',c.name,'phone',c.phone,'address',c.address) from public.rental_customers c where c.id=b.customer_id),'vehicle',(select jsonb_build_object('registration_number',v.registration_number,'make',v.make,'model',v.model) from public.vehicles v where v.id=b.vehicle_id),'business',(select to_jsonb(x) from public.rental_business x where x.id)),uid) returning * into inv;
   -- Allocate all net advances to the new invoice; do not consume security deposits.
   insert into public.rental_allocations(invoice_id,ledger_id,amount_minor)
   select inv.id,l.id,case when l.kind='refund' then -l.amount_minor else l.amount_minor end from public.rental_ledger l where l.booking_id=b.id and l.kind in ('payment','refund','deposit_apply');
   select coalesce(sum(amount_minor),0) into paid from public.rental_allocations where invoice_id=inv.id;
   if paid>inv.total_minor then raise exception 'Advances exceed final invoice. Refund the excess before issuance'; end if;
   result:=to_jsonb(inv);
  elsif p_action='invoice_void' then
   select * into strict inv from public.rental_invoices where rental_invoices.id=(p_payload->>'invoice_id')::uuid and status='issued';
   select coalesce(sum(amount_minor),0) into paid from public.rental_allocations where invoice_id=inv.id;
   if paid<>0 then raise exception 'Refund allocated payments before voiding'; end if;
   if length(trim(coalesce(p_payload->>'reason','')))=0 then raise exception 'Void reason required'; end if;
   update public.rental_invoices set status='void',void_reason=p_payload->>'reason' where rental_invoices.id=inv.id;
   result:=jsonb_build_object('id',inv.id,'status','void');
  else
   if p_action<>'deposit_apply' and coalesce(p_payload->>'method','cash') not in ('cash','bank','card') then raise exception 'Choose cash, bank or externally processed card'; end if;
   amount:=(p_payload->>'amount_minor')::bigint;
   if amount is null or amount<=0 then raise exception 'Positive amount required'; end if;
   select coalesce(sum(case when kind in ('payment','deposit_apply') then amount_minor when kind='refund' then -amount_minor else 0 end),0),coalesce(sum(case when kind='deposit' then amount_minor when kind in ('deposit_refund','deposit_apply') then -amount_minor else 0 end),0)
    into paid,deposit from public.rental_ledger where booking_id=b.id;
   select * into inv from public.rental_invoices where booking_id=b.id and status='issued';
   if p_action in ('payment','deposit','deposit_apply') and b.status='cancelled' then raise exception 'Cancelled booking accepts refunds only'; end if;
   if p_action in ('deposit_refund','deposit_apply') and amount>deposit then raise exception 'Insufficient deposit balance'; end if;
   if p_action='deposit_apply' and inv.id is null then raise exception 'Issue an invoice before applying a deposit'; end if;
   if p_action='refund' and amount>paid then raise exception 'Refund exceeds received rental payments'; end if;
   if p_action in ('refund','deposit_refund','deposit_apply') and length(trim(coalesce(p_payload->>'reason','')))=0 then raise exception 'Reason required'; end if;
   if p_action in ('payment','deposit_apply') and inv.id is not null and paid+amount>inv.total_minor then raise exception 'Payment exceeds outstanding balance'; end if;
   n:=nextval('rental_private.receipt_number');
   insert into public.rental_ledger(booking_id,receipt_number,kind,amount_minor,method,reference,reason,created_by)
   values(b.id,'RCT-'||lpad(n::text,greatest(7,length(n::text)),'0'),p_action,amount,case when p_action='deposit_apply' then 'deposit' else coalesce(p_payload->>'method','cash') end,coalesce(p_payload->>'reference',''),coalesce(p_payload->>'reason',''),uid) returning rental_ledger.id into ledger_id;
   if inv.id is not null and p_action in ('payment','refund','deposit_apply') then
    insert into public.rental_allocations values(inv.id,ledger_id,case when p_action='refund' then -amount else amount end);
   end if;
   result:=jsonb_build_object('id',ledger_id);
  end if;
 end if;
 insert into public.audit_logs(actor_user_id,action,entity_type,entity_id,metadata)
 values(uid,'RENTAL_'||upper(p_action),'rental',coalesce(id::text,''),jsonb_build_object('request_id',p_request_id,'reason',coalesce(p_payload->>'reason',''),'amount_minor',p_payload->'amount_minor','discount_minor',p_payload->'discount_minor','tax_bps',p_payload->'tax_bps'));
 insert into rental_private.requests(actor,request_id,action,payload_hash,response) values(uid,p_request_id,p_action,md5(p_payload::text),result);
 return result;
end $$;
-- Existing guards, RLS, grants, immutable snapshots and retry records are retained.
notify pgrst, 'reload schema';

-- Tenuli Auto Care 1.12: immutable receiving/completion notes and explicit handover.
-- Apply after TENULI_SIMPLE_BILLING_UPGRADE.sql, or use ENABLE_AUTOMART.sql.

alter table repair_private.jobs add column if not exists received_at timestamptz;
alter table repair_private.jobs add column if not exists completed_at timestamptz;
create sequence if not exists repair_private.service_note_no;
create table if not exists repair_private.service_documents(
 id uuid primary key default gen_random_uuid(),job_id uuid not null references repair_private.jobs(id),
 kind text not null check(kind in('receiving','completion')),series_number text not null,revision integer not null check(revision>0),
 number text not null unique,parent_id uuid references repair_private.service_documents(id),job_revision integer not null,
 snapshot jsonb not null,created_at timestamptz not null default now(),created_by uuid not null references auth.users(id),
 unique(job_id,kind,revision)
);
create table if not exists repair_private.handovers(
 job_id uuid primary key references repair_private.jobs(id),completion_document_id uuid not null references repair_private.service_documents(id),
 handed_over_at timestamptz not null default now(),recipient text not null,notes text not null default '',created_by uuid not null references auth.users(id)
);
alter table repair_private.service_documents enable row level security;
alter table repair_private.handovers enable row level security;
revoke all on repair_private.service_documents,repair_private.handovers,repair_private.service_note_no from public,anon,authenticated;
create or replace function repair_private.service_immutable() returns trigger language plpgsql set search_path='' as $$
begin raise exception 'Issued documents and handover events are immutable. Issue a numbered correction.';end $$;
drop trigger if exists service_documents_immutable on repair_private.service_documents;
create trigger service_documents_immutable before update or delete on repair_private.service_documents for each row execute function repair_private.service_immutable();
drop trigger if exists handovers_immutable on repair_private.handovers;
create trigger handovers_immutable before update or delete on repair_private.handovers for each row execute function repair_private.service_immutable();
create or replace function repair_private.service_job_state() returns trigger language plpgsql set search_path='' as $$
begin
 if exists(select 1 from repair_private.handovers where job_id=old.id) and (new.status is distinct from old.status or new.info is distinct from old.info or new.lines is distinct from old.lines) then
  raise exception 'Vehicle already handed over. Create a new job for further repairs.';
 end if;
 if new.status is distinct from old.status then
  new.completed_at:=case when new.status='completed' then now() else null end;
 end if;
 return new;
end $$;
drop trigger if exists service_job_state on repair_private.jobs;
create trigger service_job_state before update on repair_private.jobs for each row execute function repair_private.service_job_state();

create or replace function repair_private.service_api(action text,p jsonb,request_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
<<service_body>>
declare
 uid uuid:=auth.uid();billflag boolean:=repair_private.can('view_repair_billing') or repair_private.can('manage_repair_payments');
 j repair_private.jobs;previous repair_private.service_documents;d repair_private.service_documents;inv repair_private.documents;
 prior repair_private.requests;handover repair_private.handovers;
 result jsonb;content jsonb:='{}';info jsonb:='{}';snap jsonb;billing jsonb:=null;kind_name text;series text;k text;v text;
 reason text:=trim(coalesce(p->>'reason',''));received timestamptz;completed timestamptz;revision_no integer;paid bigint;credits bigint;
begin
 if not (repair_private.can('view_repairs') or repair_private.can('manage_repairs') or billflag) then raise exception 'Repair access denied';end if;
 if action='list' then
  result:=repair_private.api('list',p,null);
  return result||jsonb_build_object('service_documents_enabled',true,
   'service_documents',(select coalesce(jsonb_agg(to_jsonb(s) order by s.created_at desc,s.revision desc),'[]') from repair_private.service_documents s where billflag or s.snapshot->'billing' is null or s.snapshot->'billing'='null'::jsonb),
   'handovers',(select coalesce(jsonb_agg(to_jsonb(h)),'[]') from repair_private.handovers h),
   'invoiced_jobs',(select coalesce(jsonb_agg(job_id),'[]') from repair_private.documents where kind='invoice' and status='issued'),
   'service_events',(select coalesce(jsonb_agg(to_jsonb(e) order by created_at desc),'[]') from repair_private.events e where e.action in('receiving_create','receiving_issue','completion_issue','handover')));
 elsif action='service_document' then
  select * into strict d from repair_private.service_documents where id=(p->>'id')::uuid;
  if d.snapshot->'billing' is not null and d.snapshot->'billing'<>'null'::jsonb and not billflag then raise exception 'Billing access denied';end if;
  return to_jsonb(d);
 end if;
 if action not in('receiving_create','receiving_issue','completion_issue','handover') then raise exception 'Unknown document action';end if;
 if not repair_private.can('manage_repairs') then raise exception 'Manage repairs permission required';end if;
 if request_id is null then raise exception 'Request ID required';end if;
 if length(reason)>1000 then raise exception 'Correction reason is too long (maximum 1000 characters)';end if;
 perform pg_advisory_xact_lock(hashtextextended('repair:'||uid::text||request_id::text,0));
 select * into prior from repair_private.requests r where r.actor=uid and r.request_id=service_api.request_id;
 if found then
  if prior.action<>service_api.action or prior.payload_hash<>md5(p::text) then raise exception 'Request key reused with different data';end if;
  if prior.response->'snapshot'->'billing' is not null and prior.response->'snapshot'->'billing'<>'null'::jsonb and not billflag then raise exception 'Billing access denied';end if;
  return prior.response;
 end if;
 -- Same lock as billing: capture one consistent invoice/payment/credit balance.
 perform pg_advisory_xact_lock(hashtextextended('tenuli-repair-finance',0));
 if action='receiving_create' then
  foreach k in array array['customer_name','phone','registration','make_model'] loop
   v:=trim(coalesce(p->>k,''));if length(v)>200 then raise exception '% is too long (maximum 200 characters)',k;end if;
   info:=info||jsonb_build_object(k,v);
  end loop;
  if info->>'customer_name'='' or info->>'registration'='' then raise exception 'Customer name and vehicle registration are required';end if;
  insert into repair_private.jobs(info,lines,created_by) values(info||'{"expected_customer_minor":0,"expected_insurer_minor":0}',
   repair_private.calc(jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'description',left(coalesce(p->>'requested_work','Inspection / diagnosis'),300),'category','Repair Items','quantity',1,'unit','job','unit_minor',null,'discount_minor',0,'tax_bps',0)))->'lines',uid) returning * into j;
 else
  select * into strict j from repair_private.jobs where id=(p->>'job_id')::uuid for update;
  if j.version is distinct from (p->>'version')::int then raise exception 'Job changed; reload and try again';end if;
 end if;
 kind_name:=case when action in('receiving_create','receiving_issue') then 'receiving' else 'completion' end;
 select * into previous from repair_private.service_documents where job_id=j.id and kind=kind_name order by revision desc limit 1;
 if coalesce((p->>'document_revision')::int,0)<>coalesce(previous.revision,0) then raise exception 'Document changed; reload the latest revision';end if;
 if previous.id is not null and reason='' and action<>'handover' then raise exception 'A correction reason is required';end if;
 if j.status='cancelled' then raise exception 'Cancelled jobs cannot issue new documents';end if;
 select * into handover from repair_private.handovers where job_id=j.id;
 if kind_name='completion' then
  if j.status<>'completed' then raise exception 'Complete the repair job before issuing a completion note or recording handover';end if;
  completed:=coalesce(j.completed_at,(select max(created_at) from repair_private.events where job_id=j.id and events.action='complete'),nullif(p->>'completed_at','')::timestamptz);
  if completed is null or completed>now() then raise exception 'Enter the actual completion date and time for this historical job';end if;
  select * into inv from repair_private.documents where job_id=j.id and kind='invoice' and status='issued';
  if inv.id is not null then
   if not billflag then raise exception 'Billing access is required to issue or hand over a job with an invoice';end if;
   paid:=repair_private.paid(j.id);
   select coalesce(sum(total_minor),0) into credits from repair_private.documents where parent_id=inv.id and kind='credit' and status='issued';
   billing:=jsonb_build_object('invoice_number',inv.number,'total_minor',inv.total_minor,'paid_minor',paid,'credit_minor',credits,'balance_minor',inv.total_minor-credits-paid,'as_of',now());
  end if;
 end if;
 if action='handover' then
  if coalesce(p->>'confirm','')<>'true' then raise exception 'Confirm the vehicle has actually been returned';end if;
  if handover.job_id is not null then raise exception 'Vehicle handover already recorded';end if;
  if previous.id is null or previous.job_revision<>j.revision or (previous.snapshot->>'completed_at')::timestamptz is distinct from completed then raise exception 'Issue a current completion note before recording handover';end if;
  v:=trim(coalesce(p->>'recipient',''));
  if v='' or length(v)>200 or length(coalesce(p->>'handover_notes',''))>1000 then raise exception 'Enter recipient (up to 200 characters) and notes up to 1000 characters';end if;
  if p ? 'handed_over_at' then raise exception 'Handover time is recorded by the server at confirmation';end if;
  insert into repair_private.handovers(job_id,completion_document_id,recipient,notes,created_by) values(j.id,previous.id,v,coalesce(p->>'handover_notes',''),uid) returning * into handover;
  content:=previous.snapshot->'content';reason:='Vehicle returned to '||v;
 else
  foreach k in array case when kind_name='receiving' then array['reported_problem','requested_work','expected_date','odometer','fuel_level','damage','condition','accessories','notes'] else array['work_performed','parts_replaced','checks','recommendations','warranty','notes'] end loop
   v:=trim(coalesce(p->>k,''));
   if length(v)>(case when k in('expected_date','odometer','fuel_level') then 100 else 2000 end) then raise exception '% is too long',k;end if;
   content:=content||jsonb_build_object(k,v);
  end loop;
  if kind_name='receiving' then
   if content->>'reported_problem'='' or content->>'requested_work'='' then raise exception 'Reported problem and requested work are required';end if;
   received:=coalesce(nullif(p->>'received_at','')::timestamptz,j.received_at,now());
   if received>now() or received>coalesce(j.completed_at,(select max(created_at) from repair_private.events where job_id=j.id and events.action='complete'),'infinity') or received>coalesce(handover.handed_over_at,'infinity') then raise exception 'Received time must be in the past and before completion or handover';end if;
   if nullif(content->>'odometer','') is not null and (content->>'odometer')::numeric<0 then raise exception 'Odometer cannot be negative';end if;
   if nullif(content->>'expected_date','') is not null and (content->>'expected_date')::date<(received at time zone 'Asia/Colombo')::date then raise exception 'Expected completion must be on or after arrival';end if;
  elsif content->>'work_performed'='' then raise exception 'Work performed is required';end if;
 end if;
 if completed<j.received_at then raise exception 'Completion cannot be before arrival';end if;
 -- Assigning a job number is not customer approval. No approval/payment fields are modified.
 update repair_private.jobs set job_number=coalesce(job_number,'TAC-JOB-'||nextval('repair_private.job_no')),
  received_at=coalesce(received,received_at),completed_at=coalesce(completed,completed_at),version=version+1,updated_at=now() where id=j.id returning * into j;
 series:=coalesce(previous.series_number,case when kind_name='receiving' then 'TAC-RN-' else 'TAC-CN-' end||nextval('repair_private.service_note_no'));
 revision_no:=coalesce(previous.revision,0)+1;
 info:='{}';foreach k in array array['customer_name','phone','registration','make_model'] loop
  v:=case when action='handover' then previous.snapshot->'info'->>k else coalesce(p->>k,j.info->>k,'') end;
  if length(v)>200 then raise exception '% is too long (maximum 200 characters)',k;end if;
  if k in('customer_name','registration') and trim(v)='' then raise exception 'Customer name and registration are required';end if;
  info:=info||jsonb_build_object(k,v);
 end loop;
 snap:=jsonb_build_object('business',(select data from repair_private.business),'info',info,'job_number',j.job_number,'content',content,
  'received_at',j.received_at,'completed_at',case when kind_name='completion' then completed end,'billing',billing,'correction_reason',reason,
  'handover',case when kind_name='completion' and handover.job_id is not null then jsonb_build_object('handed_over_at',handover.handed_over_at,'recipient',handover.recipient,'notes',handover.notes) end);
 insert into repair_private.service_documents(job_id,kind,series_number,revision,number,parent_id,job_revision,snapshot,created_by)
 values(j.id,kind_name,series,revision_no,series||'-R'||revision_no,previous.id,j.revision,snap,uid) returning * into d;
 result:=to_jsonb(d);
 insert into repair_private.events(job_id,actor,action,reason) values(j.id,uid,action,case when reason='' then d.number else reason end);
 insert into repair_private.requests values(uid,request_id,action,md5(p::text),result);
 return result;
end $$;
revoke all on function repair_private.service_immutable(),repair_private.service_job_state(),repair_private.service_api(text,jsonb,uuid) from public,anon,authenticated;
grant execute on function repair_private.service_api(text,jsonb,uuid) to authenticated;
create or replace function public.repair_api(p_action text,p_payload jsonb default '{}',p_request_id uuid default null) returns jsonb language sql security invoker set search_path='' as $$
 select case when p_action in('list','service_document','receiving_create','receiving_issue','completion_issue','handover') then repair_private.service_api(p_action,p_payload,p_request_id) else repair_private.api(p_action,p_payload,p_request_id) end;
$$;
revoke all on function public.repair_api(text,jsonb,uuid) from public,anon;
grant execute on function public.repair_api(text,jsonb,uuid) to authenticated;
notify pgrst,'reload schema';

-- Tenuli Auto Care 1.13: grouped customer documents and immutable layout revisions.
-- Apply after TENULI_SERVICE_DOCUMENTS_UPGRADE.sql, or use ENABLE_AUTOMART.sql.

do $$ begin
 if to_regprocedure('repair_private.service_api(text,jsonb,uuid)') is null then
  raise exception 'Install the service-document update first, or run ENABLE_AUTOMART.sql';
 end if;
end $$;
create or replace function repair_private.work_section(value text) returns text language sql immutable set search_path='' as $$
 select case lower(trim(coalesce(value,'')))
 when 'replacement items' then 'Replacement Items'
 when 'remove & refit items' then 'Removal & Refitting Items'
 when 'removal & refitting items' then 'Removal & Refitting Items'
 when 'remove and refixed items' then 'Removal & Refitting Items'
 when 'paint items' then 'Paint Items' else 'Repair Items' end;
$$;
create or replace function repair_private.grouped_snapshot(s jsonb) returns jsonb language sql immutable set search_path='' as $$
 select jsonb_set(s||jsonb_build_object('template_version','grouped-v1'),'{calculation,lines}',
  coalesce((select jsonb_agg(x||jsonb_build_object('category',repair_private.work_section(x->>'category')) order by ord)
   from jsonb_array_elements(s->'calculation'->'lines') with ordinality as a(x,ord) where not coalesce((x->>'excluded')::boolean,false)),'[]'::jsonb));
$$;
create or replace function repair_private.grouped_document_insert() returns trigger language plpgsql set search_path='' as $$
begin
 if new.kind in('estimate','invoice') then
  new.snapshot:=repair_private.grouped_snapshot(new.snapshot);
  if new.kind='invoice' then
   new.snapshot:=new.snapshot||jsonb_build_object('settlement',jsonb_build_object('paid_minor',repair_private.paid(new.job_id),'credit_minor',0,'balance_minor',new.total_minor-repair_private.paid(new.job_id),'as_of',now()));
  end if;
 end if;
 return new;
end $$;
drop trigger if exists grouped_document_insert on repair_private.documents;
create trigger grouped_document_insert before insert on repair_private.documents for each row execute function repair_private.grouped_document_insert();
create table if not exists repair_private.document_copies(
 id uuid primary key default gen_random_uuid(),source_document_id uuid not null references repair_private.documents(id),
 job_id uuid not null references repair_private.jobs(id),number text not null unique,kind text not null check(kind in('estimate','invoice')),
 copy_revision integer not null check(copy_revision>0),snapshot jsonb not null,total_minor bigint not null,
 created_at timestamptz not null default now(),created_by uuid not null references auth.users(id),unique(source_document_id,copy_revision)
);
alter table repair_private.document_copies enable row level security;
revoke all on repair_private.document_copies from public,anon,authenticated;
create index if not exists repair_document_copies_job on repair_private.document_copies(job_id);
drop trigger if exists document_copies_immutable on repair_private.document_copies;
create trigger document_copies_immutable before update or delete on repair_private.document_copies for each row execute function repair_private.service_immutable();
create or replace function repair_private.grouped_api(action text,p jsonb,request_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare
 uid uuid:=auth.uid();billflag boolean:=repair_private.can('view_repair_billing') or repair_private.can('manage_repair_payments');
 d repair_private.documents;c repair_private.document_copies;prior repair_private.requests;result jsonb;s jsonb;
 rev int;paid bigint;credits bigint;reason text:=trim(coalesce(p->>'reason',''));
begin
 if not (repair_private.can('view_repairs') or repair_private.can('manage_repairs') or billflag) then raise exception 'Repair access denied';end if;
 if action='list' then
  return repair_private.service_api('list',p,null)||jsonb_build_object('grouped_billing',true,'document_copies',
   (select coalesce(jsonb_agg(to_jsonb(v)||jsonb_build_object('status',original.status,'is_layout_copy',true) order by v.created_at desc),'[]')
    from repair_private.document_copies v join repair_private.documents original on original.id=v.source_document_id where v.kind='estimate' or billflag));
 elsif action='document_copy' then
  select * into strict c from repair_private.document_copies where id=(p->>'id')::uuid;
  if c.kind='invoice' and not billflag then raise exception 'Billing access denied';end if;
  return to_jsonb(c)||jsonb_build_object('is_layout_copy',true,'status',(select status from repair_private.documents where id=c.source_document_id));
 elsif action<>'document_reissue' then raise exception 'Unknown grouped-document action';end if;
 select * into strict d from repair_private.documents where id=(p->>'document_id')::uuid and kind in('estimate','invoice');
 if not repair_private.can(case when d.kind='invoice' then 'manage_repair_payments' else 'manage_repairs' end) then raise exception 'Document revision permission denied';end if;
 if request_id is null then raise exception 'Request ID required';end if;
 perform pg_advisory_xact_lock(hashtextextended('repair:'||uid::text||request_id::text,0));
 select * into prior from repair_private.requests r where r.actor=uid and r.request_id=grouped_api.request_id;
 if found then
  if prior.action<>grouped_api.action or prior.payload_hash<>md5(p::text) then raise exception 'Request key reused with different data';end if;
  return prior.response;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('tenuli-repair-finance',0));
 select * into strict d from repair_private.documents where id=d.id for update;
 if d.status<>'issued' then raise exception 'A void document cannot be reissued';end if;
 if length(reason) not between 1 and 1000 then raise exception 'Enter a revision reason (maximum 1000 characters)';end if;
 select coalesce(max(copy_revision),0) into rev from repair_private.document_copies where source_document_id=d.id;
 if rev is distinct from (p->>'copy_revision')::int then raise exception 'Document changed; reload the revision history';end if;
 s:=repair_private.grouped_snapshot(d.snapshot)||jsonb_build_object('original_number',d.number,'original_issued_at',d.created_at,'copy_revision',rev+1,'correction_reason',reason);
 if d.kind='invoice' then
  paid:=repair_private.paid(d.job_id);
  select coalesce(sum(total_minor),0) into credits from repair_private.documents where parent_id=d.id and kind='credit' and status='issued';
  s:=s||jsonb_build_object('settlement',jsonb_build_object('paid_minor',paid,'credit_minor',credits,'balance_minor',d.total_minor-credits-paid,'as_of',now()));
 end if;
 insert into repair_private.document_copies(source_document_id,job_id,number,kind,copy_revision,snapshot,total_minor,created_by)
 values(d.id,d.job_id,d.number||'-COPY-R'||(rev+1),d.kind,rev+1,s,d.total_minor,uid) returning * into c;
 result:=to_jsonb(c)||jsonb_build_object('status',d.status,'is_layout_copy',true);
 insert into repair_private.events(job_id,actor,action,reason) values(d.job_id,uid,'document_reissue',reason);
 insert into repair_private.requests values(uid,request_id,action,md5(p::text),result);
 return result;
end $$;
revoke all on function repair_private.work_section(text),repair_private.grouped_snapshot(jsonb),repair_private.grouped_document_insert(),repair_private.grouped_api(text,jsonb,uuid) from public,anon,authenticated;
grant execute on function repair_private.grouped_api(text,jsonb,uuid) to authenticated;
create or replace function public.repair_api(p_action text,p_payload jsonb default '{}',p_request_id uuid default null) returns jsonb language sql security invoker set search_path='' as $$
 select case when p_action in('list','document_copy','document_reissue') then repair_private.grouped_api(p_action,p_payload,p_request_id)
 when p_action in('service_document','receiving_create','receiving_issue','completion_issue','handover') then repair_private.service_api(p_action,p_payload,p_request_id)
 else repair_private.api(p_action,p_payload,p_request_id) end;
$$;
revoke all on function public.repair_api(text,jsonb,uuid) from public,anon;
grant execute on function public.repair_api(text,jsonb,uuid) to authenticated;
notify pgrst,'reload schema';

-- Tenuli 1.14: two customer documents, atomic receiving advances and final-bill copies.
-- Additive: existing documents, payments and financial totals are never rewritten.

do $$ begin
 if to_regprocedure('repair_private.grouped_api(text,jsonb,uuid)') is null then raise exception 'Install grouped billing first, or run ENABLE_AUTOMART.sql';end if;
end $$;
alter table repair_private.jobs add column if not exists completion_details jsonb not null default '{}';
alter table repair_private.payments add column if not exists purpose text check(purpose in('advance','balance'));
alter table repair_private.handovers alter column completion_document_id drop not null;
alter table repair_private.handovers add column if not exists final_document_id uuid references repair_private.documents(id);

create or replace function repair_private.payment_purpose() returns trigger language plpgsql set search_path='' as $$
begin
 new.purpose:=case when exists(select 1 from repair_private.documents where job_id=new.job_id and kind='invoice' and status='issued') then 'balance' else 'advance' end;
 return new;
end $$;
drop trigger if exists payment_purpose on repair_private.payments;
create trigger payment_purpose before insert on repair_private.payments for each row execute function repair_private.payment_purpose();

create or replace function repair_private.payment_summary(jid uuid,invoice_id uuid,invoice_total bigint) returns jsonb language sql stable set search_path='' as $$
 with amounts as (
  select coalesce(sum(amount_minor) filter(where kind='payment' and coalesce(purpose,case when created_at<=coalesce((select min(created_at) from repair_private.documents where job_id=jid and kind='invoice'),'infinity') then 'advance' else 'balance' end)='advance'),0)::bigint as advance,
   coalesce(sum(amount_minor) filter(where kind='payment' and coalesce(purpose,case when created_at<=coalesce((select min(created_at) from repair_private.documents where job_id=jid and kind='invoice'),'infinity') then 'advance' else 'balance' end)='balance'),0)::bigint as other,
   coalesce(sum(amount_minor) filter(where kind='refund'),0)::bigint as refunds
  from repair_private.payments where job_id=jid
 ), credit as (select coalesce(sum(total_minor),0)::bigint as total from repair_private.documents where parent_id=invoice_id and kind='credit' and status='issued')
 select jsonb_build_object('total_minor',invoice_total,'advance_minor',a.advance,'other_payments_minor',a.other,'refund_minor',a.refunds,'paid_minor',a.advance+a.other-a.refunds,'credit_minor',c.total,'balance_minor',invoice_total-c.total-a.advance-a.other+a.refunds,'as_of',now()) from amounts a cross join credit c;
$$;
create or replace function repair_private.receiving_ack_insert() returns trigger language plpgsql set search_path='' as $$
declare ack jsonb;begin
 if new.kind='receiving' then
  select jsonb_build_object('advance_minor',coalesce(sum(amount_minor),0),'payments',coalesce(jsonb_agg(jsonb_build_object('number',number,'amount_minor',amount_minor,'created_at',created_at,'method',method,'reference',reference) order by created_at,number),'[]')) into ack
  from repair_private.payments where job_id=new.job_id and kind='payment' and coalesce(purpose,case when created_at<=coalesce((select min(created_at) from repair_private.documents where job_id=new.job_id and kind='invoice'),'infinity') then 'advance' else 'balance' end)='advance';
  if (ack->>'advance_minor')::bigint>0 and not (repair_private.can('view_repair_billing') or repair_private.can('manage_repair_payments')) then raise exception 'Billing access is required for a receiving note with an advance';end if;
  new.snapshot:=new.snapshot||jsonb_build_object('template_version','receiving-advance-v1','payment_ack',ack);
  -- Existing service-document authorization also protects the advance snapshot.
  if (ack->>'advance_minor')::bigint>0 then new.snapshot:=new.snapshot||jsonb_build_object('billing',ack);end if;
 end if;
 return new;
end $$;
drop trigger if exists receiving_ack_insert on repair_private.service_documents;
create trigger receiving_ack_insert before insert on repair_private.service_documents for each row execute function repair_private.receiving_ack_insert();

create or replace function repair_private.final_snapshot(s jsonb,jid uuid,invoice_id uuid,invoice_total bigint) returns jsonb language plpgsql stable set search_path='' as $$
declare j repair_private.jobs;completion jsonb;begin
 select * into strict j from repair_private.jobs where id=jid;
 completion:=case when (j.completion_details->>'job_revision')::int=j.revision then j.completion_details else s->'completion' end;
 if coalesce(completion->'content'->>'work_performed','')='' then return s;end if;
 return s||jsonb_build_object('template_version','final-bill-v1','completion',completion,'settlement',repair_private.payment_summary(jid,invoice_id,invoice_total));
end $$;
create or replace function repair_private.final_document_insert() returns trigger language plpgsql set search_path='' as $$
begin
 new.snapshot:=new.snapshot||jsonb_build_object('customer_document_policy','two-a4-v1');
 if new.kind='invoice' then new.snapshot:=repair_private.final_snapshot(new.snapshot,new.job_id,new.id,new.total_minor);end if;
 return new;
end $$;
drop trigger if exists two_document_insert on repair_private.documents;
create trigger two_document_insert before insert on repair_private.documents for each row execute function repair_private.final_document_insert();
create or replace function repair_private.final_copy_insert() returns trigger language plpgsql set search_path='' as $$
begin
 new.snapshot:=new.snapshot||jsonb_build_object('customer_document_policy','two-a4-v1');
 if new.kind='invoice' then new.snapshot:=repair_private.final_snapshot(new.snapshot,new.job_id,new.source_document_id,new.total_minor);end if;
 return new;
end $$;
drop trigger if exists two_copy_insert on repair_private.document_copies;
create trigger two_copy_insert before insert on repair_private.document_copies for each row execute function repair_private.final_copy_insert();

create or replace function repair_private.two_document_api(action text,p jsonb,request_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare
 uid uuid:=auth.uid();billflag boolean:=repair_private.can('view_repair_billing') or repair_private.can('manage_repair_payments');
 j repair_private.jobs;d repair_private.documents;prior repair_private.requests;hand repair_private.handovers;
 result jsonb;res jsonb;info jsonb:='{}';content jsonb:='{}';payload jsonb;summary jsonb;completion jsonb;
 k text;v text;reason text:=trim(coalesce(p->>'reason',''));advance bigint:=0;amount bigint;completed timestamptz;
begin
 if not (repair_private.can('view_repairs') or repair_private.can('manage_repairs') or billflag) then raise exception 'Repair access denied';end if;
 if action='list' then
  return repair_private.grouped_api('list',p,null)||jsonb_build_object('two_document_workflow',true,'workflow_events',(select coalesce(jsonb_agg(to_jsonb(e) order by created_at desc),'[]') from repair_private.events e where e.action in('arrival_create','arrival_issue','final_issue','final_reissue','collect_balance','final_handover')));
 elsif action='bill_status' then
  if not billflag then raise exception 'Billing access denied';end if;
  select * into strict d from repair_private.documents where id=(p->>'document_id')::uuid and kind='invoice';
  return repair_private.payment_summary(d.job_id,d.id,d.total_minor)||jsonb_build_object('invoice_id',d.id,'invoice_number',d.number,'invoice_status',d.status,'job_id',d.job_id);
 end if;
 if action in('arrival_create','arrival_issue') then
  if not repair_private.can('manage_repairs') then raise exception 'Manage repairs permission required';end if;
  advance:=case when p ? 'advance_minor' then repair_private.amount(p,'advance_minor') else 0 end;
  if advance>0 and not repair_private.can('manage_repair_payments') then raise exception 'Payment permission required to receive an advance';end if;
 elsif action in('final_issue','final_reissue','collect_balance') then
  if not repair_private.can('manage_repair_payments') then raise exception 'Payment permission required';end if;
 elsif action='final_handover' then
  if not repair_private.can('manage_repairs') or not billflag then raise exception 'Repair management and billing access required';end if;
 else raise exception 'Unknown two-document action';end if;
 if request_id is null then raise exception 'Request ID required';end if;
 perform pg_advisory_xact_lock(hashtextextended('repair:'||uid::text||request_id::text,0));
 select * into prior from repair_private.requests r where r.actor=uid and r.request_id=two_document_api.request_id;
 if found then
  if prior.action<>two_document_api.action or prior.payload_hash<>md5(p::text) then raise exception 'Request key reused with different data';end if;
  if action in('arrival_create','arrival_issue') and prior.response->'snapshot'->'billing'<>'null'::jsonb and not billflag then raise exception 'Billing access denied';end if;
  return prior.response;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('tenuli-repair-finance',0));
 if length(reason)>1000 then raise exception 'Reason too long';end if;
 if action='arrival_create' then
  foreach k in array array['customer_name','phone','registration','make_model'] loop
   v:=trim(coalesce(p->>k,''));if length(v)>200 then raise exception '% is too long',k;end if;info:=info||jsonb_build_object(k,v);
  end loop;
  res:=repair_private.api('save',jsonb_build_object('info',info,'lines',jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'description',left(coalesce(p->>'requested_work','Inspection / diagnosis'),300),'category','Repair Items','quantity',1,'unit','job','unit_minor',null,'discount_minor',0,'tax_bps',0))),gen_random_uuid());
  select * into strict j from repair_private.jobs where id=(res->>'id')::uuid;
 else
  select * into strict j from repair_private.jobs where id=(p->>'job_id')::uuid for update;
  if action<>'collect_balance' and j.version is distinct from (p->>'version')::int then raise exception 'Job changed; reload and try again';end if;
 end if;
 if action in('arrival_create','arrival_issue') then
  if advance>0 then
   if coalesce(p->>'confirm_advance','')<>'true' then raise exception 'Confirm that the advance was actually received';end if;
   if exists(select 1 from repair_private.documents where job_id=j.id and kind='invoice' and status='issued') or exists(select 1 from repair_private.handovers where job_id=j.id) then raise exception 'Use Collect Balance for invoiced jobs';end if;
   if coalesce(p->>'method','') not in('cash','bank','card') then raise exception 'Select a payment method';end if;
   if length(coalesce(p->>'reference',''))>200 then raise exception 'Payment reference is too long';end if;
   perform repair_private.api('payment',jsonb_build_object('job_id',j.id,'amount_minor',advance,'payer','customer','method',p->>'method','reference',coalesce(p->>'reference',''),'reason','Advance at vehicle receiving'),gen_random_uuid());
  end if;
  result:=repair_private.service_api('receiving_issue',p||jsonb_build_object('job_id',j.id,'version',j.version),gen_random_uuid());
 elsif action in('final_issue','final_reissue') then
  if j.status<>'completed' then raise exception 'Complete the job before issuing a final bill';end if;
  completed:=coalesce(j.completed_at,(select max(created_at) from repair_private.events where job_id=j.id and events.action='complete'),nullif(p->>'completed_at','')::timestamptz);
  if completed is null or completed>now() or completed<j.received_at then raise exception 'Enter the actual completion date and time';end if;
  foreach k in array array['work_performed','parts_replaced','recommendations','warranty','checks','notes'] loop
   v:=trim(coalesce(p->>k,''));if length(v)>2000 then raise exception '% is too long (maximum 2000 characters)',k;end if;content:=content||jsonb_build_object(k,v);
  end loop;
  if content->>'work_performed'='' then raise exception 'Work performed is required';end if;
  completion:=jsonb_build_object('content',content,'completed_at',completed,'job_revision',j.revision);
  update repair_private.jobs set completion_details=completion,completed_at=completed,version=version+1,updated_at=now() where id=j.id returning * into j;
  if action='final_issue' then
   result:=repair_private.api('invoice_issue',p||jsonb_build_object('job_id',j.id,'version',j.version),gen_random_uuid());
  else
   select * into strict d from repair_private.documents where id=(p->>'document_id')::uuid and job_id=j.id and kind='invoice' and status='issued';
   result:=repair_private.grouped_api('document_reissue',p||jsonb_build_object('document_id',d.id),gen_random_uuid());
  end if;
 elsif action='collect_balance' then
  if coalesce(p->>'confirm','')<>'true' then raise exception 'Confirm that payment was actually received';end if;
  if coalesce(p->>'method','') not in('cash','bank','card') then raise exception 'Select a payment method';end if;
  if length(coalesce(p->>'reference',''))>200 then raise exception 'Payment reference is too long';end if;
  select * into strict d from repair_private.documents where id=(p->>'document_id')::uuid and job_id=j.id and kind='invoice' and status='issued' for update;
  summary:=repair_private.payment_summary(j.id,d.id,d.total_minor);
  if (summary->>'balance_minor')::bigint is distinct from (p->>'expected_balance_minor')::bigint then raise exception 'Balance changed; refresh before collecting payment';end if;
  amount:=repair_private.amount(p,'amount_minor');
  if amount<=0 or amount>(summary->>'balance_minor')::bigint then raise exception 'Payment must be positive and cannot exceed the balance';end if;
  res:=repair_private.api('payment',p||jsonb_build_object('reason',case when reason='' then 'Final bill balance payment' else reason end,'payer',coalesce(nullif(p->>'payer',''),'customer')),gen_random_uuid());
  result:=jsonb_build_object('payment_id',res->'id','invoice_id',d.id,'settlement',repair_private.payment_summary(j.id,d.id,d.total_minor));
 elsif action='final_handover' then
  if j.status<>'completed' then raise exception 'Complete the job before handover';end if;
  if coalesce(p->>'confirm','')<>'true' then raise exception 'Confirm the vehicle has actually been returned';end if;
  if p ? 'handed_over_at' then raise exception 'Handover time is recorded by the server';end if;
  if exists(select 1 from repair_private.handovers where job_id=j.id) then raise exception 'Vehicle handover already recorded';end if;
  select * into strict d from repair_private.documents where job_id=j.id and kind='invoice' and status='issued';
  if d.snapshot->>'template_version' is distinct from 'final-bill-v1' and not exists(select 1 from repair_private.document_copies where source_document_id=d.id and snapshot->>'template_version'='final-bill-v1') then raise exception 'Issue the combined final bill first';end if;
  v:=trim(coalesce(p->>'recipient',''));
  if v='' or length(v)>200 or length(coalesce(p->>'handover_notes',''))>1000 then raise exception 'Enter recipient (up to 200 characters) and notes up to 1000 characters';end if;
  insert into repair_private.handovers(job_id,final_document_id,recipient,notes,created_by) values(j.id,d.id,v,coalesce(p->>'handover_notes',''),uid) returning * into hand;
  update repair_private.jobs set version=version+1,updated_at=now() where id=j.id;
  result:=to_jsonb(hand);reason:='Vehicle returned to '||v;
 end if;
 insert into repair_private.events(job_id,actor,action,reason) values(j.id,uid,action,case when reason='' then coalesce(result->>'number',action) else reason end);
 insert into repair_private.requests values(uid,request_id,action,md5(p::text),result);
 return result;
end $$;
revoke all on function repair_private.payment_purpose(),repair_private.payment_summary(uuid,uuid,bigint),repair_private.receiving_ack_insert(),repair_private.final_snapshot(jsonb,uuid,uuid,bigint),repair_private.final_document_insert(),repair_private.final_copy_insert(),repair_private.two_document_api(text,jsonb,uuid) from public,anon,authenticated;
grant execute on function repair_private.two_document_api(text,jsonb,uuid) to authenticated;
create or replace function public.repair_api(p_action text,p_payload jsonb default '{}',p_request_id uuid default null) returns jsonb language sql security invoker set search_path='' as $$
 select case when p_action in('list','bill_status','arrival_create','arrival_issue','final_issue','final_reissue','collect_balance','final_handover') then repair_private.two_document_api(p_action,p_payload,p_request_id)
 when p_action in('document_copy','document_reissue') then repair_private.grouped_api(p_action,p_payload,p_request_id)
 when p_action in('service_document','receiving_create','receiving_issue','completion_issue','handover') then repair_private.service_api(p_action,p_payload,p_request_id)
 else repair_private.api(p_action,p_payload,p_request_id) end;
$$;
revoke all on function public.repair_api(text,jsonb,uuid) from public,anon;
grant execute on function public.repair_api(text,jsonb,uuid) to authenticated;
notify pgrst,'reload schema';

-- Tenuli 1.15: choose the modern A4 renderer for future customer snapshots only.
-- No UPDATE of history, finance changes, new tables or permission changes.

do $$ begin
 if to_regprocedure('repair_private.two_document_api(text,jsonb,uuid)') is null then raise exception 'Install the two-document workflow first, or run the current ENABLE_AUTOMART.sql';end if;
end $$;
create or replace function repair_private.modern_customer_layout() returns trigger language plpgsql set search_path='' as $$
begin
 if new.snapshot->>'template_version' in('receiving-advance-v1','final-bill-v1') then
  new.snapshot:=new.snapshot||jsonb_build_object('layout_version','modern-a4-v1');
 end if;
 return new;
end $$;
revoke all on function repair_private.modern_customer_layout() from public,anon,authenticated;
-- PostgreSQL runs same-kind triggers alphabetically; enrich only after the existing snapshot triggers.
drop trigger if exists zz_modern_customer_layout on repair_private.service_documents;
create trigger zz_modern_customer_layout before insert on repair_private.service_documents for each row execute function repair_private.modern_customer_layout();
drop trigger if exists zz_modern_customer_layout on repair_private.documents;
create trigger zz_modern_customer_layout before insert on repair_private.documents for each row execute function repair_private.modern_customer_layout();
drop trigger if exists zz_modern_customer_layout on repair_private.document_copies;
create trigger zz_modern_customer_layout before insert on repair_private.document_copies for each row execute function repair_private.modern_customer_layout();
notify pgrst,'reload schema';

-- Tenuli Auto Care 1.17: internal pricing reviews and six work categories.
-- Apply after 1.16 or run the generated ENABLE_AUTOMART.sql. Repeatable; no historical rewrites.

select pg_advisory_xact_lock(hashtextextended('tenuli-repair-finance',0));
create unique index if not exists repair_photo_draft_unique on repair_private.jobs ((info->>'photo_draft_id')) where coalesce(info->>'photo_draft_id','')<>'';
create table if not exists repair_private.price_reviews (
 id uuid primary key default gen_random_uuid(), job_id uuid not null references repair_private.jobs(id),
 parent_id uuid references repair_private.price_reviews(id), kind text not null check(kind in('item','package')),
 status text not null check(status in('pending','accepted','rejected','not_required')),
 source_version integer not null, original_lines jsonb not null, proposed_minor bigint,
 allocations jsonb not null default '[]', reason text not null, supporting_note text not null default '',
 recorded_by uuid not null references auth.users(id), recorded_at timestamptz not null default now(),
 unique(parent_id), check(proposed_minor is null or proposed_minor between 0 and 1000000000000)
);
create index if not exists price_reviews_job on repair_private.price_reviews(job_id,recorded_at);
alter table repair_private.price_reviews enable row level security;
revoke all on repair_private.price_reviews from public,anon,authenticated;
drop trigger if exists price_reviews_immutable on repair_private.price_reviews;
create trigger price_reviews_immutable before update or delete on repair_private.price_reviews for each row execute function repair_private.service_immutable();
create or replace function repair_private.work_section(value text) returns text language sql immutable set search_path='' as $$
 select case lower(trim(coalesce(value,'')))
 when 'replacement items' then 'Replacement Items'
 when 'remove & refit items' then 'Removal & Refitting Items'
 when 'removal & refitting items' then 'Removal & Refitting Items'
 when 'remove and refixed items' then 'Removal & Refitting Items'
 when 'paint items' then 'Paint Items'
 when 'miscellaneous items' then 'Miscellaneous Items'
 when 'other charges' then 'Other Charges' else 'Repair Items' end;
$$;
-- Protected allocations may only be reused for the same job, line and quoted inputs.
create or replace function repair_private.validate_agreements(p jsonb) returns void language plpgsql set search_path='' as $$
declare x jsonb; a jsonb; review repair_private.price_reviews; original jsonb; begin
 for x in select value from jsonb_array_elements(p->'lines') loop
  if x->>'agreed_minor' is not null or x->>'price_review_id' is not null then
   select * into review from repair_private.price_reviews where id=(x->>'price_review_id')::uuid and job_id=(p->>'job_id')::uuid and status='accepted';
   if not found then raise exception 'An accepted price review is required';end if;
   select e into a from jsonb_array_elements(review.allocations) e where e->>'id'=x->>'id';
   select e into original from jsonb_array_elements(review.original_lines) e where e->>'id'=x->>'id';
   if a is null or original is null or (a->>'amount_minor')::bigint is distinct from (x->>'agreed_minor')::bigint or
      (original->'quantity') is distinct from (x->'quantity') or
      (original->'unit_minor') is distinct from (x->'unit_minor') or
      (original->'discount_minor') is distinct from (x->'discount_minor') then
    raise exception 'Agreed pricing changed; clear the agreement and create a new review';end if;
  end if;
 end loop;
end $$;
create or replace function repair_private.calc(input jsonb) returns jsonb language plpgsql immutable set search_path='' as $$
declare x jsonb; arr jsonb:='[]'; q numeric; price bigint; discount bigint; tax int; base bigint; taxsum bigint:=0; netsum bigint:=0; pending int:=0; excluded boolean; begin
 if jsonb_typeof(input) is distinct from 'array' or jsonb_array_length(input) not between 1 and 200 then raise exception 'Add 1 to 200 items'; end if;
 if exists(select 1 from jsonb_array_elements(input) e group by e->>'id' having count(*)>1) or exists(select 1 from jsonb_array_elements(input) e where length(trim(coalesce(e->>'id','')))=0) then raise exception 'Unique nonempty item IDs required';end if;
 for x in select value from jsonb_array_elements(input) loop
  if length(trim(coalesce(x->>'description',''))) not between 1 and 300 then raise exception 'Item description required (max 300 characters)'; end if;
  q:=(x->>'quantity')::numeric;
  if q is null or q<=0 or q>100000 or q<>round(q,3) then raise exception 'Invalid item quantity'; end if;
  price:=case when x->>'unit_minor' is null then null else repair_private.amount(x,'unit_minor') end;
  discount:=repair_private.amount(x,'discount_minor');tax:=(x->>'tax_bps')::int;excluded:=coalesce((x->>'excluded')::boolean,false);
  if tax is null or tax not between 0 and 10000 then raise exception 'Invalid tax'; end if;
  base:=case when price is null then null else round(q*price)::bigint-discount end;
  if x->>'agreed_minor' is not null then base:=repair_private.amount(x,'agreed_minor');end if;
  if base<0 then raise exception 'Discount exceeds line price'; end if;
  if not excluded then
   if base is null then pending:=pending+1; else netsum:=netsum+base;taxsum:=taxsum+round(base*tax/10000.0)::bigint;end if;
  end if;
  arr:=arr||jsonb_build_array(jsonb_build_object('id',coalesce(x->>'id',md5(x::text||jsonb_array_length(arr)::text)),'category',left(coalesce(x->>'category','Repair Items'),100),'description',trim(x->>'description'),'quantity',q,'unit',left(coalesce(x->>'unit','item'),30),'unit_minor',price,'discount_minor',discount,'tax_bps',tax,'excluded',excluded,'notes',left(coalesce(x->>'notes',''),500),'position',left(coalesce(x->>'position',''),60),'internal_note',left(coalesce(x->>'internal_note',''),1000),'unverified_note',left(coalesce(x->>'unverified_note',''),500),'agreed_minor',case when x->>'agreed_minor' is null then null else base end,'price_review_id',x->>'price_review_id','net_minor',case when excluded then 0 else base end,'tax_minor',case when excluded then 0 when base is null then null else round(base*tax/10000.0)::bigint end));
 end loop;
 if netsum>1000000000000 then raise exception 'Total too large'; end if;
 return jsonb_build_object('lines',arr,'net_minor',netsum,'tax_minor',taxsum,'total_minor',netsum+taxsum,'pending',pending);
end $$;
create or replace function repair_private.api(action text,p jsonb,request_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
<<repair_body>>
declare uid uuid:=auth.uid(); jid uuid; bid uuid; sid uuid; j repair_private.jobs; b repair_private.bills; d repair_private.documents; prior repair_private.requests;
 result jsonb; cal jsonb; info jsonb; k text; perm text; reason text:=trim(coalesce(p->>'reason','')); amount bigint; tax bigint; total bigint; paid bigint; q numeric; allocated numeric; count_rows int; new_id uuid; due date; existing bigint; oldqty numeric; billflag boolean; remaining_net bigint; remaining_tax bigint; split jsonb;
begin
 if uid is null or not public.current_user_is_active() or public.current_user_role() not in('administrator','insurance_officer') then raise exception 'Active staff account required' using errcode='42501';end if;
 if action in('list','document') then
  if not (repair_private.can('view_repairs') or repair_private.can('manage_repairs') or repair_private.can('view_repair_billing') or repair_private.can('manage_repair_payments')) then raise exception 'Repair access denied' using errcode='42501';end if;
 elsif action in('shop_list','attachment_get') then
  if not(repair_private.can('manage_shop_costs') or repair_private.can('view_job_profit')) then raise exception 'Shop access denied' using errcode='42501';end if;
 elsif action in('report','report_export') then
  if not repair_private.can('view_job_profit') or (action='report_export' and not repair_private.can('export_repair_reports')) then raise exception 'Profit/report access denied' using errcode='42501';end if;
 else
  perm:=case when action in('supplier_save','bill_save','bill_confirm','allocation','cost_credit','supplier_payment','supplier_refund','costs_complete','attachment_link') then 'manage_shop_costs'
   when action in('invoice_issue','invoice_void','customer_credit','payment','refund') then 'manage_repair_payments'
   when action='business_save' then 'manage_system_settings' else 'manage_repairs' end;
  if not repair_private.can(perm) then raise exception 'Permission required: %',perm using errcode='42501';end if;
 end if;
 billflag:=repair_private.can('view_repair_billing') or repair_private.can('manage_repair_payments');
 if action='list' then
  return jsonb_build_object('simple_billing',true,'business',(select to_jsonb(v) from repair_private.business v),'jobs',(select coalesce(jsonb_agg(to_jsonb(v)-'costs_complete' order by v.updated_at desc),'[]') from repair_private.jobs v),
   'documents',(select coalesce(jsonb_agg(to_jsonb(v) order by v.created_at desc),'[]') from repair_private.documents v where billflag or v.kind='estimate'),
   'payments',(select coalesce(jsonb_agg(to_jsonb(v) order by v.created_at desc),'[]') from repair_private.payments v where billflag),
   'events',(select coalesce(jsonb_agg(to_jsonb(v) order by v.created_at desc),'[]') from repair_private.events v where v.action in('save','send','approve','reject','start','complete','cancel','insurer_decision')));
 elsif action='document' then
  select * into strict d from repair_private.documents where id=(p->>'id')::uuid;
  if d.kind<>'estimate' and not billflag then raise exception 'Billing access denied';end if;
  return to_jsonb(d);
 elsif action='shop_list' then
  return jsonb_build_object('simple_billing',true,'suppliers',(select coalesce(jsonb_agg(to_jsonb(v)),'[]') from repair_private.suppliers v),'bills',(select coalesce(jsonb_agg(to_jsonb(v) order by v.created_at desc),'[]') from repair_private.bills v),'allocations',(select coalesce(jsonb_agg(to_jsonb(v)),'[]') from repair_private.cost_parts v),'credits',(select coalesce(jsonb_agg(to_jsonb(v)),'[]') from repair_private.cost_credits v),'payments',(select coalesce(jsonb_agg(to_jsonb(v)),'[]') from repair_private.supplier_payments v),'jobs',(select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'number',coalesce(v.job_number,v.number),'customer',v.info->>'customer_name','vehicle',v.info->>'registration','costs_complete',v.costs_complete,'lines',v.lines)),'[]') from repair_private.jobs v));
 elsif action in('report','report_export') then
  return (select coalesce(jsonb_agg(v),'[]') from (select repair_private.profit(r) as v from repair_private.jobs r where r.status<>'cancelled') s
   where coalesce((v->>'invoice_date')::timestamptz,(v->>'created_at')::timestamptz) at time zone 'Asia/Colombo'>=coalesce(nullif(p->>'from','')::date,'1900-01-01'::date)
   and coalesce((v->>'invoice_date')::timestamptz,(v->>'created_at')::timestamptz) at time zone 'Asia/Colombo'<coalesce(nullif(p->>'to','')::date,'9998-12-31'::date)+1);
 end if;
 if request_id is null then raise exception 'Request ID required';end if;
 perform pg_advisory_xact_lock(hashtextextended('repair:'||uid::text||request_id::text,0));
 select * into prior from repair_private.requests r where r.actor=uid and r.request_id=api.request_id;
 if found then
  if prior.action<>api.action or prior.payload_hash<>md5(p::text) then raise exception 'Request key reused with different data';end if;
  return prior.response;
 end if;
 -- Financial operations serialize within this single-business module, preventing crossed job/bill lock order.
 perform pg_advisory_xact_lock(hashtextextended('tenuli-repair-finance',0));
 jid:=nullif(p->>'job_id','')::uuid;bid:=nullif(p->>'bill_id','')::uuid;
 if jid is not null then select * into strict j from repair_private.jobs where id=jid for update;end if;
 if bid is not null then select * into strict b from repair_private.bills where id=bid for update;end if;
 if length(reason)>1000 then raise exception 'Reason too long';end if;
 if action='save' then
  perform repair_private.validate_agreements(p);
  if exists(select 1 from jsonb_array_elements(p->'lines') x where coalesce((x->>'tax_bps')::int,0)<>0) then
   raise exception 'Use simple pricing: reopen the estimate in the updated app before saving';end if;
  cal:=repair_private.calc((select jsonb_agg(x||jsonb_build_object('tax_bps',0)) from jsonb_array_elements(p->'lines') x));info:='{}';
  foreach k in array array['customer_name','phone','address','registration','make_model','vehicle_id','accident_date','insurance','policy_number','claim_number','valid_until','advisor','expected_date','notes','reported_problem','requested_work','assessor_details','chassis_number','manufacture_notes','photo_draft_id'] loop
   info:=info||jsonb_build_object(k,left(coalesce(p->'info'->>k,''),case when k in('notes','address') then 1000 else 200 end));
  end loop;
  if trim(info->>'customer_name')='' or trim(info->>'registration')='' then raise exception 'Customer and vehicle registration required';end if;
  foreach k in array array['accident_date','valid_until','expected_date'] loop perform nullif(info->>k,'')::date;end loop;
  if coalesce(info->>'vehicle_id','')<>'' and not exists(select 1 from public.vehicles where id=(info->>'vehicle_id')::uuid) then raise exception 'Vehicle not found';end if;
  info:=info||jsonb_build_object('expected_customer_minor',repair_private.amount(jsonb_build_object('expected_customer_minor',coalesce(p->'info'->>'expected_customer_minor','0')),'expected_customer_minor'),'expected_insurer_minor',repair_private.amount(jsonb_build_object('expected_insurer_minor',coalesce(p->'info'->>'expected_insurer_minor','0')),'expected_insurer_minor'));
  if jid is not null and coalesce(j.info->>'photo_draft_id','')<>'' then info:=info||jsonb_build_object('photo_draft_id',j.info->'photo_draft_id');end if;
  if jid is null then
   if coalesce(info->>'photo_draft_id','')<>'' and exists(select 1 from repair_private.jobs where jobs.info->>'photo_draft_id'=repair_body.info->>'photo_draft_id') then raise exception 'This photo draft already belongs to a saved estimate. Reopen that estimate; do not create it again.';end if;
   insert into repair_private.jobs(info,lines,created_by) values(info,cal->'lines',uid) returning * into j;jid:=j.id;
  else
   if exists(select 1 from repair_private.documents where job_id=jid and kind='invoice' and status='issued') then raise exception 'Issued invoice exists; use credit or void before revising';end if;
   if j.status='cancelled' or reason='' then raise exception 'Revision reason required; cancelled jobs cannot change';end if;
   update repair_private.jobs set info=repair_body.info,lines=cal->'lines',version=version+1,revision=revision+1,status='draft',customer_approval='pending',insurer_approval='not_requested',updated_at=now() where id=jid and version=(p->>'version')::int returning * into j;
   if not found then raise exception 'Job changed; reload before editing' using errcode='40001';end if;
  end if;
  result:=to_jsonb(j)-'costs_complete';
 elsif action in('send','approve','reject','start','complete','cancel','insurer_decision') then
  if j.id is null or j.version is distinct from (p->>'version')::int then raise exception 'Job changed; reload' using errcode='40001';end if;
  if reason='' then raise exception 'Reason / approval reference required';end if;
  if action='send' then
   if j.status<>'draft' then raise exception 'Only draft estimates can be sent';end if;
   cal:=repair_private.calc(j.lines);
   insert into repair_private.documents(job_id,number,kind,snapshot,net_minor,tax_minor,total_minor,created_by) values(jid,j.number||'-R'||j.revision,'estimate',repair_private.snapshot(j), (cal->>'net_minor')::bigint,(cal->>'tax_minor')::bigint,(cal->>'total_minor')::bigint,uid);
   j.status:='sent';
  elsif action='approve' then if j.status not in('draft','sent') then raise exception 'Estimate is not awaiting approval';end if;j.status:='approved';j.customer_approval:='approved';j.job_number:=coalesce(j.job_number,'TAC-JOB-'||nextval('repair_private.job_no'));
  elsif action='reject' then if j.status not in('draft','sent') then raise exception 'Estimate is not awaiting approval';end if;j.status:='rejected';j.customer_approval:='rejected';
  elsif action='start' then if j.status<>'approved' then raise exception 'Approve estimate first';end if;j.status:='in_progress';
  elsif action='complete' then if j.status<>'in_progress' then raise exception 'Start the job first';end if;j.status:='completed';
  elsif action='cancel' then
   if exists(select 1 from repair_private.documents where job_id=jid and kind='invoice' and status='issued') or repair_private.paid(jid)<>0 or exists(select 1 from repair_private.cost_parts where job_id=jid and (not confirmed or cash_paid_minor<>0)) or coalesce((select sum(actual_minor) from repair_private.cost_parts where job_id=jid),0)<>coalesce((select sum(net_minor) from repair_private.cost_credits where job_id=jid),0) then raise exception 'Settle/refund billing, credit allocated costs and settle supplier cash before cancellation';end if;j.status:='cancelled';
  else if j.status='cancelled' or p->>'decision' not in('pending','approved','rejected','not_requested') or p->>'decision' is null then raise exception 'Invalid insurer decision';end if;j.insurer_approval:=p->>'decision';end if;
  update repair_private.jobs set status=j.status,customer_approval=j.customer_approval,insurer_approval=j.insurer_approval,job_number=j.job_number,version=version+1,updated_at=now() where id=jid returning * into j;
  result:=to_jsonb(j)-'costs_complete';
 elsif action='invoice_issue' then
  if j.id is null or j.version is distinct from (p->>'version')::int or j.status<>'completed' or j.customer_approval<>'approved' then raise exception 'Complete the approved job and reload before invoicing';end if;
  cal:=repair_private.calc(j.lines);if (cal->>'pending')::int>0 then raise exception 'Resolve or explicitly exclude every price-pending item';end if;
  if (cal->>'tax_minor')::bigint<>0 then raise exception 'Revise this older estimate using simple pricing, then approve and complete it before issuing a new invoice';end if;
  due:=(p->>'due_date')::date;if due is null then raise exception 'Due date required';end if;
  if repair_private.paid(jid)>(cal->>'total_minor')::bigint then raise exception 'Refund excess advance before issuing';end if;
  insert into repair_private.documents(job_id,number,kind,snapshot,net_minor,tax_minor,total_minor,created_by) values(jid,'TAC-INV-'||nextval('repair_private.document_no'),'invoice',repair_private.snapshot(j)||jsonb_build_object('due_date',due),(cal->>'net_minor')::bigint,(cal->>'tax_minor')::bigint,(cal->>'total_minor')::bigint,uid) returning to_jsonb(documents) into result;
 elsif action in('invoice_void','customer_credit') then
  select * into strict d from repair_private.documents where id=(p->>'document_id')::uuid and kind='invoice' and status='issued' for update;jid:=d.job_id;
  if reason='' then raise exception 'Correction reason required';end if;
  if action='invoice_void' then
   if repair_private.paid(jid)<>0 then raise exception 'Refund received money before voiding';end if;
   update repair_private.documents set status='void' where id=d.id;result:=jsonb_build_object('voided',d.id);
  else
   if p ? 'amount_minor' then
    select d.net_minor-coalesce(sum(net_minor),0),d.tax_minor-coalesce(sum(tax_minor),0) into remaining_net,remaining_tax from repair_private.documents where parent_id=d.id;
    split:=repair_private.split_credit(repair_private.amount(p,'amount_minor'),remaining_net,remaining_tax);
    amount:=(split->>'net')::bigint;tax:=(split->>'tax')::bigint;
   else amount:=repair_private.amount(p,'net_minor');tax:=repair_private.amount(p,'tax_minor');end if;
   if amount+tax<=0 or amount+coalesce((select sum(net_minor) from repair_private.documents where parent_id=d.id),0)>d.net_minor or tax+coalesce((select sum(tax_minor) from repair_private.documents where parent_id=d.id),0)>d.tax_minor then raise exception 'Credit exceeds invoice';end if;
   insert into repair_private.documents(job_id,number,kind,parent_id,snapshot,net_minor,tax_minor,total_minor,created_by) values(jid,'TAC-CR-'||nextval('repair_private.document_no'),'credit',d.id,jsonb_build_object('business',d.snapshot->'business','info',d.snapshot->'info','original_number',d.number,'reason',reason,'calculation',jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('description',reason,'category','Credit','quantity',1,'net_minor',amount,'tax_minor',tax,'unit_minor',amount)),'net_minor',amount,'tax_minor',tax,'total_minor',amount+tax,'pending',0)),amount,tax,amount+tax,uid) returning to_jsonb(documents) into result;
  end if;
 elsif action in('payment','refund') then
  if j.id is null then raise exception 'Choose a job';end if;
  amount:=repair_private.amount(p,'amount_minor');paid:=repair_private.paid(jid);
  if amount<=0 or reason='' then raise exception 'Positive amount and reason required';end if;
  if action='refund' then if amount>paid then raise exception 'Refund exceeds amount received';end if;
  else
   if j.status in('cancelled','rejected') then raise exception 'Job cannot receive payments';end if;
   select * into d from repair_private.documents where job_id=jid and kind='invoice' and status='issued';
   if found then total:=d.total_minor-coalesce((select sum(total_minor) from repair_private.documents where parent_id=d.id),0);if paid+amount>total then raise exception 'Payment exceeds balance';end if;end if;
  end if;
  insert into repair_private.payments(job_id,kind,amount_minor,payer,method,reference,reason,snapshot,created_by) values(jid,action,amount,p->>'payer',p->>'method',left(coalesce(p->>'reference',''),200),reason,repair_private.snapshot(j),uid) returning to_jsonb(payments) into result;
 elsif action='supplier_save' then
  info:='{}';foreach k in array array['name','contact','phone','address','terms'] loop info:=info||jsonb_build_object(k,left(coalesce(p->>k,''),500));end loop;
  if trim(info->>'name')='' then raise exception 'Supplier name required';end if;sid:=nullif(p->>'id','')::uuid;
  if sid is null then insert into repair_private.suppliers(data) values(info) returning id into sid;
  else update repair_private.suppliers set data=info,version=version+1 where id=sid and version=(p->>'version')::int;if not found then raise exception 'Supplier changed; reload';end if;end if;
  result:=jsonb_build_object('id',sid);
 elsif action='bill_save' then
  q:=(p->>'quantity')::numeric;if q is null or q<=0 or q>100000 or q<>round(q,3) then raise exception 'Invalid quantity';end if;
  if trim(coalesce(p->>'description',''))='' then raise exception 'Description required';end if;
  amount:=repair_private.amount(p,'estimated_minor');total:=case when p->>'actual_minor' is null then null else repair_private.amount(p,'actual_minor') end;tax:=0;
  if coalesce((p->>'tax_minor')::bigint,0)<>0 then raise exception 'Use simple pricing: record the full shop cost as one amount';end if;
  insert into repair_private.bills(supplier_id,description,category,quantity,unit,estimated_minor,actual_minor,tax_minor,reference,purchase_date,due_date,terms)
   values(nullif(p->>'supplier_id','')::uuid,left(p->>'description',300),left(coalesce(p->>'category','Parts'),100),q,left(coalesce(p->>'unit','item'),30),amount,total,tax,left(coalesce(p->>'reference',''),200),(p->>'purchase_date')::date,nullif(p->>'due_date','')::date,left(coalesce(p->>'terms',''),500)) returning to_jsonb(bills) into result;
 elsif action='bill_confirm' then
  if b.id is null or b.actual_minor is not null or b.version is distinct from (p->>'version')::int or reason='' then raise exception 'Unconfirmed bill, current version and reason required';end if;
  if p ? 'amount_minor' then
   total:=repair_private.amount(p,'amount_minor');tax:=b.tax_minor;amount:=total-tax;
   if amount<0 then raise exception 'Confirmed cost is below the original adjustment; review this historical bill';end if;
  else
   amount:=repair_private.amount(p,'actual_minor');tax:=b.tax_minor;
   if coalesce((p->>'tax_minor')::bigint,0)<>tax then raise exception 'Original bill adjustment must be preserved';end if;
  end if;
  update repair_private.bills set actual_minor=amount,tax_minor=tax,version=version+1 where id=bid returning to_jsonb(bills) into result;
  update repair_private.jobs set costs_complete=false where id in(select job_id from repair_private.allocations where bill_id=bid);
 elsif action='allocation' then
  if b.id is null or j.id is null or j.status='cancelled' then raise exception 'Choose a bill and active job';end if;
  q:=(p->>'quantity')::numeric;if q is null or q<=0 or q<>round(q,3) then raise exception 'Invalid quantity';end if;
  select coalesce(sum(quantity),0) into allocated from repair_private.allocations where bill_id=bid;
  if exists(select 1 from repair_private.cost_credits where bill_id=bid and job_id is null) then raise exception 'This bill has unused-stock credits. Reverse the remaining unused stock on this bill before recording its adjusted replacement purchase';end if;
  if allocated+q>b.quantity then raise exception 'Allocation exceeds purchased quantity';end if;
  if coalesce(p->>'line_id','')<>'' and not exists(select 1 from jsonb_array_elements(j.lines) x where x->>'id'=p->>'line_id') then raise exception 'Invalid repair line';end if;
  insert into repair_private.allocations(bill_id,job_id,line_id,quantity) values(bid,jid,nullif(p->>'line_id',''),q) returning to_jsonb(allocations) into result;
  update repair_private.jobs set costs_complete=false where id=jid;
 elsif action='cost_credit' then
  if b.id is null or b.actual_minor is null or reason='' then raise exception 'Confirmed bill and reason required';end if;
  if p ? 'amount_minor' then
   if jid is not null then
    select cp.actual_minor into remaining_net from repair_private.cost_parts cp where cp.bill_id=bid and cp.job_id=jid;
    if not found then raise exception 'Choose a job allocated to this bill';end if;
    select (round(b.tax_minor*a.cum/b.quantity)-round(b.tax_minor*(a.cum-a.quantity)/b.quantity))::bigint into remaining_tax
    from (select z.*,sum(quantity) over(order by created_at,id) as cum from repair_private.allocations z where z.bill_id=bid) a where a.job_id=jid;
   else
    select b.actual_minor-coalesce(sum(actual_minor),0) into remaining_net from repair_private.cost_parts where bill_id=bid;
    select b.tax_minor-round(b.tax_minor*coalesce(sum(quantity),0)/b.quantity)::bigint into remaining_tax from repair_private.allocations where bill_id=bid;
   end if;
   select remaining_net-coalesce(sum(net_minor),0),remaining_tax-coalesce(sum(tax_minor),0) into remaining_net,remaining_tax from repair_private.cost_credits where bill_id=bid and job_id is not distinct from jid;
   split:=repair_private.split_credit(repair_private.amount(p,'amount_minor'),remaining_net,remaining_tax);
   amount:=(split->>'net')::bigint;tax:=(split->>'tax')::bigint;
  else amount:=repair_private.amount(p,'net_minor');tax:=repair_private.amount(p,'tax_minor');end if;
  q:=coalesce((p->>'quantity')::numeric,0);
  if amount+tax<=0 or q<0 or q<>round(q,3) then raise exception 'Invalid credit amount / quantity';end if;
  select coalesce(sum(net_minor),0) into existing from repair_private.cost_credits where bill_id=bid;
  if existing+amount>b.actual_minor or tax+coalesce((select sum(tax_minor) from repair_private.cost_credits where bill_id=bid),0)>b.tax_minor then raise exception 'Credit exceeds purchase';end if;
  if jid is not null then
   select actual_minor,quantity into total,oldqty from repair_private.cost_parts where bill_id=bid and job_id=jid;
   if not found or amount+coalesce((select sum(net_minor) from repair_private.cost_credits where bill_id=bid and job_id=jid),0)>total or q+coalesce((select sum(quantity) from repair_private.cost_credits where bill_id=bid and job_id=jid),0)>oldqty then raise exception 'Credit exceeds job allocation';end if;
  else
   total:=b.actual_minor-coalesce((select sum(actual_minor) from repair_private.cost_parts where bill_id=bid),0);oldqty:=b.quantity-coalesce((select sum(quantity) from repair_private.allocations where bill_id=bid),0);
   if amount+coalesce((select sum(net_minor) from repair_private.cost_credits where bill_id=bid and job_id is null),0)>total or q+coalesce((select sum(quantity) from repair_private.cost_credits where bill_id=bid and job_id is null),0)>oldqty then raise exception 'Choose the allocated job for this credit';end if;
  end if;
  insert into repair_private.cost_credits(bill_id,job_id,net_minor,tax_minor,quantity,reason) values(bid,jid,amount,tax,q,reason) returning to_jsonb(cost_credits) into result;
 elsif action in('supplier_payment','supplier_refund') then
  if b.id is null or b.actual_minor is null or reason='' then raise exception 'Confirmed bill and reason required';end if;
  amount:=repair_private.amount(p,'amount_minor');paid:=repair_private.bill_paid(bid);total:=b.actual_minor+b.tax_minor-coalesce((select sum(net_minor+tax_minor) from repair_private.cost_credits where bill_id=bid),0);
  if amount<=0 or (action='supplier_payment' and paid+amount>total) or (action='supplier_refund' and amount>greatest(0,paid-total)) then raise exception 'Payment/refund exceeds supplier balance';end if;
  if p->>'method' not in('cash','bank','card') or p->>'method' is null then raise exception 'Payment method required';end if;
  insert into repair_private.supplier_payments(bill_id,kind,amount_minor,method,reference,reason) values(bid,case action when 'supplier_payment' then 'payment' else 'refund' end,amount,p->>'method',left(coalesce(p->>'reference',''),200),reason) returning to_jsonb(supplier_payments) into result;
 elsif action='costs_complete' then
  if j.id is null or reason='' or exists(select 1 from repair_private.cost_parts where job_id=jid and not confirmed) then raise exception 'Confirm all costs and enter a reason';end if;
  update repair_private.jobs set costs_complete=true where id=jid;result:=jsonb_build_object('saved',true);
 elsif action='attachment_link' then
  if b.id is null or not coalesce(p->>'path','') ~ ('^'||bid::text||'/[0-9a-f-]+\.(pdf|png|jpg|webp)$') then raise exception 'Invalid attachment path';end if;
  update repair_private.bills set attachment_path=p->>'path',version=version+1 where id=bid;result:=jsonb_build_object('saved',true);
 elsif action='business_save' then
  if public.current_user_role()<>'administrator' then raise exception 'Administrator required';end if;
  info:='{}';foreach k in array array['name','address','phone','email','notes','logo'] loop info:=info||jsonb_build_object(k,coalesce(p->>k,''));end loop;
  if length(info::text)>400000 or trim(info->>'name')='' or not ((info->>'logo')='/tenuli-logo.svg' or (info->>'logo') ~ '^data:image/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$') then raise exception 'Use a name and PNG/JPEG/WebP logo smaller than 280 KB';end if;
  update repair_private.business set data=info,version=version+1 where version=(p->>'version')::int;if not found then raise exception 'Business settings changed; reload';end if;
  result:=jsonb_build_object('saved',true);
 else raise exception 'Unknown repair action';end if;
 insert into repair_private.events(job_id,actor,action,reason) values(jid,uid,action,reason);
 insert into public.audit_logs(actor_user_id,action,entity_type,entity_id,metadata) values(uid,'repair_'||action,'repair',coalesce(jid,bid,sid)::text,jsonb_build_object('reason',reason));
 insert into repair_private.requests values(uid,request_id,action,md5(p::text),result);
 return result;
end $$;
create or replace function repair_private.snapshot(j repair_private.jobs) returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object('business',(select data from repair_private.business),'info',j.info,
 'calculation',jsonb_set(repair_private.calc(j.lines),'{lines}',
  (select jsonb_agg(x-'internal_note'-'unverified_note'-'price_review_id') from jsonb_array_elements(repair_private.calc(j.lines)->'lines') x)),
 'estimate_number',j.number,'job_number',j.job_number,'revision',j.revision,
 'customer_approval',j.customer_approval,'insurer_approval',j.insurer_approval);
$$;
-- Allocate known quotations only. M/R must be resolved explicitly before package pricing.
create or replace function repair_private.package_allocations(lines jsonb,total bigint) returns jsonb language plpgsql immutable set search_path='' as $$
declare result jsonb; denominator numeric; begin
 if total is null or total<0 or total>1000000000000 then raise exception 'Invalid package amount';end if;
 if exists(select 1 from jsonb_array_elements(lines) x where x->>'net_minor' is null or coalesce((x->>'excluded')::boolean,false)) then raise exception 'Confirm all selected prices; M/R cannot be used as a package weight';end if;
 select sum((x->>'net_minor')::numeric) into denominator from jsonb_array_elements(lines) x;
 if denominator is null or denominator<=0 then raise exception 'Package quotations must have a positive total';end if;
 with weights as(select x->>'id' id,(x->>'net_minor')::numeric*total/denominator exact from jsonb_array_elements(lines) x),
 parts as(select id,floor(exact)::bigint base,exact-floor(exact) rem from weights),
 ranked as(select *,row_number() over(order by rem desc,id collate "C") n,total-sum(base) over() remainder from parts)
 select jsonb_agg(jsonb_build_object('id',id,'amount_minor',base+case when n<=remainder then 1 else 0 end) order by id collate "C") into result from ranked;
 return result;
end $$;
create or replace function repair_private.price_api(action text,p jsonb,request_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); j repair_private.jobs; prior repair_private.requests; review repair_private.price_reviews;
 rec repair_private.price_reviews; rows jsonb; allocations jsonb; result jsonb; decision text; target bigint; reason text:=trim(coalesce(p->>'reason','')); begin
 if not repair_private.can('manage_repairs') then raise exception 'Permission required: manage_repairs' using errcode='42501';end if;
 if request_id is null then raise exception 'Request ID required';end if;
 perform pg_advisory_xact_lock(hashtextextended('repair:'||uid::text||request_id::text,0));
 select * into prior from repair_private.requests r where r.actor=uid and r.request_id=price_api.request_id;
 if found then
  if prior.action<>price_api.action or prior.payload_hash<>md5(p::text) then raise exception 'Request key reused with different data';end if;
  return prior.response;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('tenuli-repair-finance',0));
 select * into strict j from repair_private.jobs where id=(p->>'job_id')::uuid for update;
 if j.version is distinct from (p->>'version')::int then raise exception 'Job changed; reload before reviewing' using errcode='40001';end if;
 if j.status='cancelled' or exists(select 1 from repair_private.documents where job_id=j.id and kind='invoice' and status='issued') or exists(select 1 from repair_private.handovers where job_id=j.id) then raise exception 'Use the existing correction workflow; issued or handed-over jobs cannot change';end if;
 if length(reason) not between 1 and 1000 or length(coalesce(p->>'supporting_note',''))>2000 then raise exception 'Review reason required (max 1000); supporting note max 2000';end if;
 if action='price_propose' then
  if p->>'kind' not in('item','package') or jsonb_typeof(p->'line_ids') is distinct from 'array' then raise exception 'Select included items';end if;
  select jsonb_agg(x) into rows from jsonb_array_elements(repair_private.calc(j.lines)->'lines') x where p->'line_ids' ? (x->>'id') and not coalesce((x->>'excluded')::boolean,false);
  if rows is null or jsonb_array_length(rows)<>jsonb_array_length(p->'line_ids') or (p->>'kind'='item' and jsonb_array_length(rows)<>1) or (p->>'kind'='package' and jsonb_array_length(rows)<2) then raise exception 'Select distinct included items';end if;
  decision:=case when p->>'status'='not_required' then 'not_required' else 'pending' end;
  target:=case when decision='not_required' then null else repair_private.amount(p,'proposed_minor') end;
  allocations:=case when decision='not_required' then '[]'::jsonb when p->>'kind'='package' then repair_private.package_allocations(rows,target) else jsonb_build_array(jsonb_build_object('id',rows->0->>'id','amount_minor',target)) end;
  insert into repair_private.price_reviews(job_id,kind,status,source_version,original_lines,proposed_minor,allocations,reason,supporting_note,recorded_by)
   values(j.id,p->>'kind',decision,j.version,rows,target,allocations,reason,coalesce(p->>'supporting_note',''),uid) returning * into rec;
 elsif action='price_decide' then
  select * into strict review from repair_private.price_reviews where id=(p->>'review_id')::uuid and job_id=j.id and status='pending';
  if exists(select 1 from repair_private.price_reviews where parent_id=review.id) then raise exception 'Review already decided';end if;
  decision:=p->>'decision';if decision is null or decision not in('accepted','rejected') then raise exception 'Explicit accept or reject required';end if;
  if decision='accepted' and review.source_version<>j.version then raise exception 'Quote revised; create a new proposal';end if;
  insert into repair_private.price_reviews(job_id,parent_id,kind,status,source_version,original_lines,proposed_minor,allocations,reason,supporting_note,recorded_by)
   values(j.id,review.id,review.kind,decision,j.version,review.original_lines,review.proposed_minor,review.allocations,reason,coalesce(p->>'supporting_note',''),uid) returning * into rec;
  if decision='accepted' then
   select jsonb_agg(case when a is null then x else x||jsonb_build_object('agreed_minor',(a->>'amount_minor')::bigint,'price_review_id',rec.id) end order by ord) into rows
    from jsonb_array_elements(j.lines) with ordinality e(x,ord)
    left join lateral(select v a from jsonb_array_elements(rec.allocations) v where v->>'id'=x->>'id') q on true;
   update repair_private.jobs set lines=repair_private.calc(rows)->'lines',version=version+1,revision=revision+1,status='draft',customer_approval='pending',insurer_approval='not_requested',updated_at=now() where id=j.id returning * into j;
  end if;
 else raise exception 'Unknown price action';end if;
 insert into repair_private.events(job_id,actor,action,reason) values(j.id,uid,action,reason);
 result:=jsonb_build_object('job',to_jsonb(j)-'costs_complete','review',to_jsonb(rec));
 insert into repair_private.requests(actor,request_id,action,payload_hash,response) values(uid,request_id,action,md5(p::text),result);
 return result;
end $$;
-- Freeze issued accounting snapshots, allowing only the existing void status transition.
create or replace function repair_private.accounting_document_guard() returns trigger language plpgsql set search_path='' as $$
begin
 if tg_op='DELETE' then raise exception 'Issued document is immutable';end if;
 if (to_jsonb(new)-'status') is distinct from (to_jsonb(old)-'status') or not(old.status='issued' and new.status='void') then raise exception 'Issued document snapshot is immutable';end if;
 return new;
end $$;
drop trigger if exists accounting_document_guard on repair_private.documents;
create trigger accounting_document_guard before update or delete on repair_private.documents for each row execute function repair_private.accounting_document_guard();
create or replace function public.repair_api(p_action text,p_payload jsonb default '{}',p_request_id uuid default null) returns jsonb language plpgsql security invoker set search_path='' as $$
declare result jsonb;begin
 if p_action in('price_propose','price_decide') then return repair_private.price_api(p_action,p_payload,p_request_id);end if;
 result:=case when p_action in('list','bill_status','arrival_create','arrival_issue','final_issue','final_reissue','collect_balance','final_handover') then repair_private.two_document_api(p_action,p_payload,p_request_id)
 when p_action in('document_copy','document_reissue') then repair_private.grouped_api(p_action,p_payload,p_request_id)
 when p_action in('service_document','receiving_create','receiving_issue','completion_issue','handover') then repair_private.service_api(p_action,p_payload,p_request_id)
 else repair_private.api(p_action,p_payload,p_request_id) end;
 if p_action='list' then result:=result||repair_private.price_list();end if;
 return result;
end $$;
create or replace function repair_private.price_list() returns jsonb language plpgsql security definer set search_path='' as $$
begin
 if not(repair_private.can('view_repairs') or repair_private.can('manage_repairs') or repair_private.can('view_repair_billing') or repair_private.can('manage_repair_payments')) then raise exception 'Repair access denied' using errcode='42501';end if;
 return jsonb_build_object('price_reviews',(select coalesce(jsonb_agg(to_jsonb(r) order by recorded_at desc),'[]') from repair_private.price_reviews r),'pricing_reviews',true);
end $$;
revoke all on function repair_private.validate_agreements(jsonb),repair_private.calc(jsonb),repair_private.snapshot(repair_private.jobs),repair_private.work_section(text),repair_private.package_allocations(jsonb,bigint),repair_private.accounting_document_guard(),repair_private.price_api(text,jsonb,uuid),repair_private.price_list() from public,anon,authenticated;
grant execute on function repair_private.price_api(text,jsonb,uuid),repair_private.price_list() to authenticated;
revoke all on function public.repair_api(text,jsonb,uuid) from public,anon;
grant execute on function public.repair_api(text,jsonb,uuid) to authenticated;
notify pgrst,'reload schema';

-- Tenuli 1.18: full operations bills and the supplied Tenuli wordmark.
-- Run after v1.17, or use the regenerated ENABLE_AUTOMART.sql installer.
-- Only future inserts are enriched. Issued snapshots and ledger rows are unchanged.

do $$ begin
 if to_regprocedure('repair_private.price_list()') is null then
  raise exception 'Install v1.17 pricing/photos first, or run the current ENABLE_AUTOMART.sql';
 end if;
end $$;

-- Set the requested brand once; later authorized Settings changes remain respected.
update repair_private.business set data=data||jsonb_build_object(
 'logo','data:image/png;base64,','brand_version','capture-2026-v1')
where data->>'brand_version' is distinct from 'capture-2026-v1';

create or replace function repair_private.modern_customer_layout() returns trigger
language plpgsql set search_path='' as $$
declare j repair_private.jobs; source jsonb; receiving jsonb; payments jsonb;
 summary jsonb; invoice_id uuid; total bigint; brand jsonb;
 billflag boolean:=repair_private.can('view_repair_billing') or repair_private.can('manage_repair_payments');
begin
 select data into brand from repair_private.business;
 -- Freeze the configured logo in each new document, including credits and copies.
 new.snapshot:=jsonb_set(new.snapshot,'{business}',
  coalesce(new.snapshot->'business','{}')||jsonb_build_object('logo',brand->'logo','brand_version',brand->'brand_version'));
 if new.snapshot->>'template_version' is null or new.snapshot->>'template_version' not in('receiving-advance-v1','final-bill-v1') then return new;end if;
 if new.snapshot->>'template_version'='receiving-advance-v1' and not billflag then
  -- Preserve the existing unpriced receiving-note capability. Never grant billing access.
  new.snapshot:=new.snapshot||jsonb_build_object('layout_version','modern-a4-v1');
  return new;
 end if;
 select * into strict j from repair_private.jobs where id=new.job_id;
 if new.kind='receiving' then
  source:=repair_private.grouped_snapshot(repair_private.snapshot(j));
  new.snapshot:=new.snapshot||jsonb_build_object(
   'info',(source->'info')||(new.snapshot->'info'),
   'calculation',source->'calculation','estimate_number',j.number,
   'job_number',j.job_number,'job_id',j.id,'job_revision',j.revision,
   'receiving_content',new.snapshot->'content');
  total:=(source->'calculation'->>'total_minor')::bigint;
  select id into invoice_id from repair_private.documents where job_id=j.id and kind='invoice' and status='issued';
  summary:=repair_private.payment_summary(j.id,invoice_id,total);
  new.snapshot:=new.snapshot||jsonb_build_object('settlement',summary,'billing',summary);
 else
  select snapshot->'content' into receiving from repair_private.service_documents
   where job_id=j.id and kind='receiving' order by revision desc limit 1;
  new.snapshot:=new.snapshot||jsonb_build_object(
   'receiving_content',coalesce(new.snapshot->'receiving_content',receiving,'{}'),
   'received_at',coalesce(new.snapshot->'received_at',to_jsonb(j.received_at)),
   'job_id',j.id,'job_number',coalesce(new.snapshot->>'job_number',j.job_number),
   'job_revision',coalesce(new.snapshot->'job_revision',new.snapshot->'revision',to_jsonb(j.revision)));
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('kind',kind,'purpose',purpose,
  'amount_minor',amount_minor,'created_at',created_at,'method',method,'reference',reference)
  order by created_at,number),'[]') into payments from repair_private.payments where job_id=j.id;
 new.snapshot:=new.snapshot||jsonb_build_object('layout_version','operations-a4-v2',
  'payment_details',payments,'prepared_by',(select full_name from public.profiles where id=new.created_by));
 return new;
end $$;
revoke all on function repair_private.modern_customer_layout() from public,anon,authenticated;

-- Payment receipts are internal ledger documents; they receive the current logo too.
create or replace function repair_private.freeze_current_brand() returns trigger
language plpgsql set search_path='' as $$
begin
 new.snapshot:=jsonb_set(new.snapshot,'{business}',coalesce(new.snapshot->'business','{}')||
  (select jsonb_build_object('logo',data->'logo','brand_version',data->'brand_version') from repair_private.business));
 return new;
end $$;
revoke all on function repair_private.freeze_current_brand() from public,anon,authenticated;
drop trigger if exists zz_freeze_current_brand on repair_private.payments;
create trigger zz_freeze_current_brand before insert on repair_private.payments
 for each row execute function repair_private.freeze_current_brand();
drop trigger if exists zz_freeze_current_brand on public.rental_invoices;
create trigger zz_freeze_current_brand before insert on public.rental_invoices
 for each row execute function repair_private.freeze_current_brand();
notify pgrst,'reload schema';

-- v1.18.1: select the blue letterhead for future issues/revisions only.
-- Requires the v1.18 operations-bill upgrade. No historical snapshot is rewritten.

do $$ begin
 if to_regprocedure('repair_private.freeze_current_brand()') is null then
  raise exception 'Install TENULI_OPERATIONS_BILL_UPGRADE.sql first, or use current ENABLE_AUTOMART.sql';
 end if;
end $$;
create or replace function repair_private.freeze_blue_letterhead() returns trigger
language plpgsql set search_path='' as $$
begin
 new.snapshot:=new.snapshot||jsonb_build_object('letterhead_style','blue-v1');
 return new;
end $$;
revoke all on function repair_private.freeze_blue_letterhead() from public,anon,authenticated;
drop trigger if exists zzz_blue_letterhead on repair_private.service_documents;
create trigger zzz_blue_letterhead before insert on repair_private.service_documents for each row execute function repair_private.freeze_blue_letterhead();
drop trigger if exists zzz_blue_letterhead on repair_private.documents;
create trigger zzz_blue_letterhead before insert on repair_private.documents for each row execute function repair_private.freeze_blue_letterhead();
drop trigger if exists zzz_blue_letterhead on repair_private.document_copies;
create trigger zzz_blue_letterhead before insert on repair_private.document_copies for each row execute function repair_private.freeze_blue_letterhead();
drop trigger if exists zzz_blue_letterhead on repair_private.payments;
create trigger zzz_blue_letterhead before insert on repair_private.payments for each row execute function repair_private.freeze_blue_letterhead();
drop trigger if exists zzz_blue_letterhead on public.rental_invoices;
create trigger zzz_blue_letterhead before insert on public.rental_invoices for each row execute function repair_private.freeze_blue_letterhead();
notify pgrst,'reload schema';

-- Tenuli Auto Care v1.19: optional shared custom catalogue.
-- The 600 built-in suggestions work without this upgrade. Run this only on the
-- existing application database to enable an administrator's explicit Save to
-- shared catalogue action. Jobs, prices, payments and issued documents are untouched.

do $$ begin
 if to_regprocedure('repair_private.can(text)') is null then
  raise exception 'Install the existing Tenuli repair module first';
 end if;
end $$;

create table if not exists repair_private.custom_catalogue (
 id uuid primary key default gen_random_uuid(),
 category text not null check(category in('Replacement Items','Removal & Refitting Items','Repair Items','Paint Items','Miscellaneous Items','Other Charges')),
 description text not null check(length(description) between 1 and 300),
 description_key text generated always as (lower(regexp_replace(btrim(description),'[[:space:]]+',' ','g'))) stored,
 unit text not null default 'item' check(length(unit) between 1 and 40),
 active boolean not null default true,
 version integer not null default 1 check(version>0),
 created_at timestamptz not null default now(),
 created_by uuid not null references auth.users(id),
 unique(category,description_key)
);
alter table repair_private.custom_catalogue enable row level security;
revoke all on repair_private.custom_catalogue from public,anon,authenticated;

create or replace function repair_private.catalogue_api(action text,p jsonb default '{}')
returns jsonb language plpgsql security definer set search_path='' as $$
declare entry repair_private.custom_catalogue; label text; section text; item_unit text; inserted boolean:=false;
begin
 if not (repair_private.can('view_repairs') or repair_private.can('manage_repairs') or repair_private.can('view_repair_billing') or repair_private.can('manage_repair_payments')) then
  raise exception 'Repair access denied' using errcode='42501';
 end if;
 if action='list' then
  return jsonb_build_object('items',(select coalesce(jsonb_agg(jsonb_build_object(
   'id',c.id,'category',c.category,'description',c.description,'aliases','[]'::jsonb,
   'unit',c.unit,'active',c.active,'version',c.version
  ) order by c.description),'[]'::jsonb) from repair_private.custom_catalogue c where c.active));
 elsif action='add' then
  if public.current_user_role()<>'administrator' or not repair_private.can('manage_system_settings') then
   raise exception 'Administrator settings permission required' using errcode='42501';
  end if;
  if jsonb_typeof(p) is distinct from 'object' or jsonb_typeof(p->'description') is distinct from 'string'
   or jsonb_typeof(p->'category') is distinct from 'string'
   or (p ? 'unit' and jsonb_typeof(p->'unit') is distinct from 'string') then
   raise exception 'Choose a section and enter a description';
  end if;
  label:=regexp_replace(btrim(p->>'description'),'[[:space:]]+',' ','g');
  section:=p->>'category'; item_unit:=btrim(coalesce(p->>'unit','item'));
  if length(label) not between 1 and 300 or length(item_unit) not between 1 and 40
   or section not in('Replacement Items','Removal & Refitting Items','Repair Items','Paint Items','Miscellaneous Items','Other Charges') then
   raise exception 'Invalid catalogue description, section or unit';
  end if;
  -- No prices, customer/job data, aliases or arbitrary input fields are stored.
  insert into repair_private.custom_catalogue(category,description,unit,created_by)
   values(section,label,item_unit,auth.uid()) on conflict(category,description_key) do nothing returning * into entry;
  inserted:=found;
  if not inserted then
   select * into strict entry from repair_private.custom_catalogue
    where category=section and description_key=lower(label);
  else
   insert into public.audit_logs(actor_user_id,action,entity_type,entity_id,metadata)
    values(auth.uid(),'repair_catalogue_add','repair_catalogue',entry.id::text,jsonb_build_object('category',section));
  end if;
  return jsonb_build_object('id',entry.id,'category',entry.category,'description',entry.description,
   'aliases','[]'::jsonb,'unit',entry.unit,'active',entry.active,'version',entry.version);
 end if;
 raise exception 'Unknown catalogue action';
end $$;
revoke all on function repair_private.catalogue_api(text,jsonb) from public,anon,authenticated;
grant execute on function repair_private.catalogue_api(text,jsonb) to authenticated;

create or replace function public.repair_catalogue_api(p_action text,p_payload jsonb default '{}')
returns jsonb language sql security invoker set search_path='' as $$
 select repair_private.catalogue_api(p_action,p_payload);
$$;
revoke all on function public.repair_catalogue_api(text,jsonb) from public,anon,authenticated;
grant execute on function public.repair_catalogue_api(text,jsonb) to authenticated;
notify pgrst,'reload schema';

-- Restore only missing administrator defaults; do not override explicit denials.
insert into public.role_permissions(role,permission_key,allowed)
select 'administrator'::public.app_role, permission_key,true from public.permissions
where permission_key in('view_rentals','manage_rentals','view_billing','manage_billing','refund_payments',
'view_repairs','manage_repairs','view_repair_billing','manage_repair_payments','manage_shop_costs','view_job_profit','export_repair_reports')
on conflict(role,permission_key) do nothing;
notify pgrst, 'reload schema';
commit;
select 'Automart database installed. Click Check access again in the app, or sign out and back in.' as next_step,
 to_regprocedure('public.rental_api(text,jsonb,uuid)') is not null as rentals_installed,
 to_regprocedure('public.repair_api(text,jsonb,uuid)') is not null as repairs_installed;
